  qStep('Która postać iloczynowa jest poprawna?',['(x + 1)(x + 5)','(x − 1)(x − 5)','(x + 1)(x − 5)','(x − 3)(x − 4)'],1,'W nawiasach wykorzystaj miejsca zerowe.','Postać iloczynowa to f(x) = (x − 1)(x − 5).')
