  qStep('Jakie są rozwiązania?',['x₁ = −½, x₂ = 2','x₁ = ½, x₂ = 2','x₁ = −2, x₂ = ½','x₁ = −1, x₂ = 2'],0,'Użyj x = (−b ± √Δ)/(2a).','x = (3 ± 5)/4, więc x₁ = −1/2 oraz x₂ = 2.')
