addQuadraticTask('q-exam-axis','q-exam','Oś symetrii i monotoniczność','Dla tego samego wykresu <span class="math">f(x) = −(x − 2)² + 5</span> wskaż przedział, w którym funkcja jest malejąca.',{a:-1,p:2,q:5},[qStep('Wybierz poprawną odpowiedź.',['(−∞, 2)','(2, +∞)','(−∞, 5)','(5, +∞)'],1,'Parabola skierowana w dół maleje po prawej stronie wierzchołka.','Oś symetrii ma równanie x = 2, więc funkcja maleje w (2, +∞).')],'1 pkt',true);
addQuadraticTask('q-exam-form','q-exam','Zmiana postaci funkcji','Która postać kanoniczna opisuje funkcję <span class="math">f(x) = x² − 4x + 3</span>?',{a:1,p:2,q:-1},[qStep('Wybierz poprawną odpowiedź.',['(x − 2)² − 1','(x + 2)² − 1','(x − 2)² + 1','(x − 4)² + 3'],0,'Uzupełnij kwadrat.','x² − 4x + 3 = (x − 2)² − 1.')],'1 pkt',true);
