addQuadraticTask('q-exam-data','q-exam','Wzór z danych o wykresie','Osią symetrii paraboli jest prosta <span class="math">x = 2</span>, a jednym z miejsc zerowych jest <span class="math">x₁ = −1</span>. Jakie jest drugie miejsce zerowe?',{a:1,p:2,q:-9,showRoots:true},[qStep('Wybierz poprawną odpowiedź.',['x₂ = 1','x₂ = 3','x₂ = 5','x₂ = 6'],2,'Miejsca zerowe leżą symetrycznie względem x = 2.','Liczba −1 leży 3 jednostki od osi x = 2, więc drugie zero to 2 + 3 = 5.')],'1 pkt',true);
