addQuadraticTask('q-exam-parameter','q-exam','Parametr i styczność','Dla jakiego m równanie <span class="math">x² − 6x + m = 0</span> ma dokładnie jedno rozwiązanie?',{a:1,p:3,q:0},[qStep('Wybierz poprawną odpowiedź.',['m = 6','m = 8','m = 9','m = 12'],2,'Dokładnie jedno rozwiązanie oznacza Δ = 0.','36 − 4m = 0, więc m = 9.')],'1 pkt',true);
addQuadraticTask('q-exam-inequality','q-exam','Nierówność kwadratowa','Rozwiąż nierówność <span class="math">x² − 9 > 0</span>.',{a:1,p:0,q:-9,showRoots:true},[qStep('Wybierz poprawną odpowiedź.',['(−3, 3)','(−∞, −3) ∪ (3, +∞)','[−3, 3]','(−∞, 3)'],1,'Rozłóż x² − 9 = (x − 3)(x + 3).','Parabola jest dodatnia na zewnątrz miejsc zerowych.')],'1 pkt',true);
addQuadraticTask('q-exam-interval','q-exam','Ekstremum w przedziale','Jaka jest najmniejsza wartość funkcji <span class="math">f(x) = x² − 2x − 3</span> w przedziale <span class="math">[0, 3]</span>?',{a:1,p:1,q:-4,showRoots:true},[qStep('Wybierz poprawną odpowiedź.',['−4','−3','0','3'],0,'Wierzchołek ma p = 1 i leży w podanym przedziale.','f(1) = 1 − 2 − 3 = −4; wartości na końcach są większe.')],'1 pkt',true);
addQuadraticTask('q-exam-context','q-exam','Zadanie w kontekście','Prostokąt ma boki długości <span class="math">x</span> oraz <span class="math">10 − x</span>. Jakie jest jego największe pole?',{a:-1,p:5,q:25},[qStep('Wybierz poprawną odpowiedź.',['20','24','25','50'],2,'Pole P(x) = x(10 − x) = −x² + 10x.','Wierzchołek ma x = 5, a P(5) = 25.')],'1 pkt',true);
