Object.assign(extraSubjectSpecs,moreSubjectSpecs());
Object.entries(extraSubjectSpecs).forEach(([course,spec])=>{
  spec.paths.forEach(path=>{path.taskIds=[addConceptTraining(course,path.id,path.title,path.concept,path.rows)];});
  const examPath=`${course}-exam`,examIds=spec.exam.map((row,index)=>addConceptExam(course,examPath,index,spec.paths[index%spec.paths.length].concept,row));
  spec.paths.push({id:examPath,n:'04',title:`Miniarkusz: ${spec.title}`,desc:'10 zadań A–D, 25 minut, kontrola odpowiedzi i diagnoza umiejętności.',taskIds:examIds,accent:'navy',exam:true});
});

const courses=[
  {id:'linear',n:'01',title:'Funkcja liniowa',desc:'Wykres, współczynniki, miejsca zerowe, proste, parametr i miniarkusz.',accent:'blue',taskIds:linearTaskIds},
  {id:'quadratic',n:'02',title:'Funkcja kwadratowa',desc:'Parabola, trzy postacie, przesunięcia, ekstrema, parametr, nierówności i miniarkusz.',accent:'purple',taskIds:quadraticPathways.flatMap(path=>path.taskIds)},
  {id:'sequences',n:'03',title:'Ciągi',desc:'Wzór ogólny, rozpoznawanie rodzaju, ciągi arytmetyczne i geometryczne, sumy, rekurencja oraz procent składany.',accent:'green',taskIds:sequencePathways.flatMap(path=>path.taskIds)},
  {id:'equations',n:'04',title:'Równania i nierówności',desc:'Równania, układy, nierówności, dziedzina, parametr i pełny miniarkusz A–D.',accent:'navy',taskIds:algebraPathways.flatMap(path=>path.taskIds)},
  ...Object.entries(extraSubjectSpecs).map(([id,spec])=>({id,n:spec.n,title:spec.title,desc:spec.desc,accent:spec.accent,taskIds:spec.paths.flatMap(path=>path.taskIds)}))
];

// Smart E8 keeps the complete panel engine, but swaps the matura curriculum
// for an exam-eight-grade curriculum before progress and exam pools are built.
if(window.SMART_E8){
  topics.splice(0,topics.length,...window.SMART_E8.topics);
  Object.keys(tasks).forEach(id=>delete tasks[id]);
  Object.keys(extraSubjectSpecs).forEach(id=>delete extraSubjectSpecs[id]);
  Object.assign(extraSubjectSpecs,window.SMART_E8.specs);
  Object.entries(extraSubjectSpecs).forEach(([course,spec])=>{
    spec.paths.forEach(path=>{path.taskIds=[addConceptTraining(course,path.id,path.title,path.concept,path.rows)];});
    const examPath=`${course}-exam`;
    const examRows=Array.from({length:5},(_,index)=>spec.paths.flatMap(path=>path.rows[index]?[{row:path.rows[index],path}]:[])).flat().slice(0,10);
    const examIds=examRows.map((entry,index)=>addConceptExam(course,examPath,index,entry.path.concept,[...entry.row.slice(0,5),entry.path.title,'1 pkt']));
    spec.paths.push({id:examPath,n:String(spec.paths.length+1).padStart(2,'0'),title:`Miniarkusz: ${spec.title}`,desc:'10 zadań A–D, 25 minut, kontrola odpowiedzi i diagnoza umiejętności.',taskIds:examIds,accent:'navy',exam:true});
  });
  const diagnosticByCourse=Object.entries(extraSubjectSpecs).map(([course,spec])=>spec.paths.filter(path=>!path.exam).flatMap(path=>path.rows.slice(0,2).map((entry,index)=>({id:`e8d-${course}-${path.id}-${index}`,course,q:entry[0],options:entry[1],correct:entry[2],why:entry[4]}))));
  const diagnosticPool=Array.from({length:Math.max(...diagnosticByCourse.map(group=>group.length))},(_,index)=>diagnosticByCourse.flatMap(group=>group[index]?[group[index]]:[])).flat();
  diagnosticQuestions.splice(0,diagnosticQuestions.length,...diagnosticPool.slice(0,20));
  courses.splice(0,courses.length,...Object.entries(extraSubjectSpecs).map(([id,spec])=>({id,n:spec.n,title:spec.title,desc:spec.desc,accent:spec.accent,taskIds:spec.paths.flatMap(path=>path.taskIds)})));
}
