 const record=saved.mastery[id]||{},attempts=Number(record.attempts)||0;if(!attempts)return 0;
 const best=Math.max(0,Math.min(100,Number(record.best)||0)),recent=Number.isFinite(record.lastScore)?Math.max(0,Math.min(100,record.lastScore)):best,streak=Math.max(0,Number(record.streak)||0),hasOpenError=saved.wrong.some(item=>item.id===id),overdue=record.due&&new Date(record.due).getTime()<=Date.now();
