function textbookCourseMeta(courseId){return window.E8_COURSE_META?.[courseId]||textbookMeta[courseId]||{goal:'Zrozumieć regułę i zastosować ją w zadaniu.',intuition:'Najpierw zrozum zależność, potem podstaw liczby.',caption:'Rysunek porządkuje dane i pokazuje najważniejszą zależność.',method:['Wypisz dane.','Wybierz wzór lub regułę.','Oblicz i sprawdź wynik.'],trap:'Zawsze sprawdź jednostkę i warunki zadania.',tips:[]};}
