  if(type==='percentagepoints')return `<svg viewBox="0 0 320 150" role="img" aria-label="Zmiana z czterdziestu do pięćdziesięciu pięciu procent"><path d="M48 126H280"/><rect class="fill" x="78" y="66" width="62" height="60" rx="8"/><rect class="hot" x="182" y="44" width="62" height="82" rx="8"/><text class="big centered" x="109" y="58">40%</text><text class="big centered" x="213" y="36">55%</text><path class="helper" d="M145 55H176M165 44L176 55L165 66"/><text class="centered" x="160" y="146">różnica: 15 p.p.</text></svg>`;
