function conceptBoard(config={},courseId=''){
  const meta=textbookCourseMeta(courseId);
  const heroType=window.E8_COURSE_HERO_VISUALS?.[courseId],heroVisual=Object.values(window.E8_PATH_VISUALS||{}).find(item=>item.type===heroType),caption=heroVisual?.caption||meta.caption;
  return `<div class="concept-board math-content"><div class="formula-figure">${formulaFigure(courseId,config)}<p class="formula-figure-caption"><b>Co pokazuje rysunek?</b>${caption}</p></div><div class="concept-formula"><span>${config.label||'NAJWAŻNIEJSZY WZÓR'}</span><strong>${config.formula||''}</strong><p>${meta.intuition}</p><div>${(config.items||[]).map((item,index)=>`<i style="--delay:${index}">${item}</i>`).join('')}</div></div></div>`;
}
const trainingVisualTypes={
  'e8-calc':'priority','e8-powers':'power','e8-number-reasoning':'numberline',
  'e8-fraction-calc':'fraction','e8-percent':'percent','e8-percent-problems':'multiplier',
  'e8-expressions':'distribution','e8-equations':'balance','e8-algebra-models':'story',
  'e8-ratio-scale':'ratio','e8-motion':'motion','e8-practical-problems':'motion',
  'e8-figures':'triangle','e8-circle-pythagoras':'pythagoras','e8-geometry-reasoning':'flow',
  'e8-solids':'cuboid','e8-coordinate':'coordinates','e8-solid-problems':'units',
  'e8-statistics':'chart','e8-probability':'probability','e8-data-reasoning':'median',
  'xpow-laws':'power','xpow-roots':'root','xpow-science':'scientific',
  'xpct-basics':'percent','xpct-changes':'multiplier','xpct-money':'percentagepoints',
  'xeq-transform':'balance','xeq-stories':'story','xeq-geometry':'check',
  'xgeo-pythagoras':'pythagoras','xgeo-circle':'circle','xgeo-composite':'composite',
  'xreason-plan':'flow','xreason-open':'flow','xreason-proof':'proof'
};
function conceptVisualType(t){
  if(window.E8_PATH_VISUAL_TYPES?.[t.path])return window.E8_PATH_VISUAL_TYPES[t.path];
  if(trainingVisualTypes[t.path])return trainingVisualTypes[t.path];
  const text=taskText(t,t.steps?.[0]||{});
  const rules=[
    [/kolejnoś|nawias|najpierw.*mnoż|mnoż.*przed|dziel.*przed|[+−-].*[·×*]|[·×*].*[+−-]/,'priority'],
    [/pierwiast|√/,'root'],[/potęg|\^|²|³/,'power'],[/notacj.*wykład|10[⁰¹²³⁴⁵⁶⁷⁸⁹]/,'scientific'],
    [/ułam|licznik|mianownik|wspóln.*mian/,'fraction'],[/procent|rabat|podwyż|obniż/,'multiplier'],
    [/proporcj|stosunek/,'ratio'],[/skala/,'scale'],[/prędko|droga|czas/,'motion'],
    [/pitagor|przeciwprostokąt/,'pythagoras'],[/koło|okrąg|promień|styczn/,'circle'],
    [/trójkąt|wysokość|pole figury/,'triangle'],[/brył|prostopadłośc|sześcian/,'cuboid'],
    [/współrzęd|układ współrzęd/,'coordinates'],[/wykres|diagram|słupk/,'chart'],
    [/median|średni|dominant/,'median'],[/prawdopodob|losow|kostk|monet/,'probability'],
    [/równan|niewiadom/,'balance'],[/wyraż|nawias.*algebr/,'distribution']
  ];
  return rules.find(([pattern])=>pattern.test(text))?.[1]||window.E8_TEXTBOOK?.[t.course]?.visuals?.[0]?.type||'flow';
}
function matchedAtlasVisual(atlas,t,pathIndex){
  const assigned=window.E8_PATH_VISUALS?.[t.path],fallback=assigned||atlas.visuals[Math.max(0,pathIndex)%atlas.visuals.length],type=assigned?.type||conceptVisualType(t),items=t.concept?.items||[];
  return {type,title:t.concept?.label||fallback.title,caption:items.length?items.join(' · '):fallback.caption};
}
function examConceptBoard(t){
  const type=conceptVisualType(t),label=t.concept?.label||t.examGroup||'DANE DO ZADANIA';
  return `<div class="exam-concept-diagram" style="--extra:${courseColor(courseById(t.course||'e8-numbers'))}"><div class="e8-training-visual-stage">${textbookMiniVisual(type)}</div><div class="exam-concept-copy"><span>${label}</span><strong>Odczytaj dane i wybierz metodę</strong><small>Rysunek porządkuje informacje. Wzór i wynik ustalasz samodzielnie.</small></div></div>`;
}
function geometryTrainingBoard(t){
  if(t.course==='trigonometry'){
    const isRight=t.path==='t-right',isIdentity=t.path==='t-identity',formula=isRight?'sin α = naprzeciw / przeciwprostokątna':isIdentity?'sin²α + cos²α = 1':'c² = a²+b²−2ab·cos γ';
    return `<div class="training-diagram trig-training-diagram"><svg viewBox="0 0 560 300" role="img" aria-label="Trójkąt z podpisanymi bokami i kątem alfa"><path class="td-side adjacent" d="M80 240H465"/><path class="td-side opposite" d="M465 240V55"/><path class="td-side hypotenuse" d="M80 240L465 55"/><path class="td-angle" d="M135 240A55 55 0 0 0 123 214"/><path class="td-square" d="M438 240V213H465"/><text x="143" y="224">α</text><text x="270" y="268">bok przy kącie</text><text x="477" y="150">bok naprzeciw</text><text x="220" y="130">przeciwprostokątna</text></svg><div><span>${t.concept?.label||'TRYGONOMETRIA'}</span><strong>${formula}</strong><small>${isRight?'Najpierw nazwij boki względem kąta α.':isIdentity?'Wynik dobierz do rodzaju i położenia kąta.':'Kąt γ leży między bokami a i b.'}</small></div></div>`;
  }
  if(t.course==='planimetry'){
    const isCircle=t.path==='p-circle',isSimilarity=t.path==='p-similarity';
    if(isCircle)return `<div class="training-diagram geometry-training-diagram"><svg class="polished-figure circle-tangent-figure" viewBox="0 0 560 300" role="img" aria-label="Koło z promieniem, średnicą i styczną w punkcie T"><circle class="td-shape figure-shape" cx="235" cy="150" r="102"/><path class="figure-diameter" d="M133 150H337"/><path class="td-helper figure-radius" d="M235 150H337"/><path class="td-tangent figure-tangent" d="M337 28V272"/><path class="td-square figure-right-angle" d="M315 150V128H337"/><circle class="figure-center" cx="235" cy="150" r="6"/><circle class="figure-touch" cx="337" cy="150" r="6"/><text class="diagram-label" x="218" y="178">O</text><text class="diagram-label" x="346" y="144">T</text><text class="diagram-label" x="283" y="136">r</text><text class="diagram-label" x="194" y="136">d = 2r</text><text class="diagram-label tangent-label" x="372" y="156">styczna</text><text class="diagram-note" x="365" y="214">OT ⟂ styczna</text></svg><div><span>KOŁO I OKRĄG</span><strong>P = πr² · l = 2πr</strong><small>Promień OT dochodzi do punktu styczności T i tworzy ze styczną kąt prosty.</small></div></div>`;
    if(isSimilarity)return `<div class="training-diagram geometry-training-diagram similar-training"><svg viewBox="0 0 560 300" role="img" aria-label="Dwa podobne trójkąty"><path class="td-shape" d="M45 225L145 100L245 225Z"/><path class="td-shape second" d="M280 225L415 55L535 225Z"/><text x="120" y="250">P₁</text><text x="395" y="250">P₂</text><text x="245" y="75">× k</text></svg><div><span>PODOBIEŃSTWO</span><strong>długości: k · pola: k²</strong><small>Odpowiadające elementy zapisuj w tej samej kolejności.</small></div></div>`;
    return `<div class="training-diagram geometry-training-diagram"><svg viewBox="0 0 560 300" role="img" aria-label="Trójkąt z wysokością"><path class="td-shape" d="M70 240L300 45L500 240Z"/><path class="td-helper" d="M300 45V240"/><path class="td-square" d="M300 214H326V240"/><text x="190" y="266">a</text><text x="313" y="145">hₐ</text><text x="360" y="85">P = ½ahₐ</text></svg><div><span>TRÓJKĄT</span><strong>a² + b² = c²</strong><small>Wysokość zawsze dobieraj do wskazanej podstawy.</small></div></div>`;
  }
  const e8Spec=extraSubjectSpecs[t.course],pathIndex=e8Spec?.paths?.findIndex(path=>path.id===t.path)??-1,atlas=window.E8_TEXTBOOK?.[t.course];
  if(pathIndex>=0&&atlas?.visuals?.length){
    const visual=matchedAtlasVisual(atlas,t,pathIndex);
    return `<div class="training-diagram e8-training-diagram" style="--extra:${courseColor(courseById(t.course))}"><div class="e8-training-visual-stage">${textbookMiniVisual(visual.type)}</div><div class="e8-training-visual-copy"><span>${visual.title}</span><strong>${t.concept?.formula||t.topic}</strong><small>${visual.caption}</small></div></div>`;
  }
  return conceptBoard(t.concept,t.course);
}
function extraTheoryPage(){const course=courseById(state.activeCourse),spec=activeExtraSpec(),first=spec.paths[0],focus=textbookFocusConfig(course.id,first.concept);return `<div class="page quadratic-theory-page extra-theory-page" style="--extra:${courseColor(course)}">${breadcrumb([{label:'Kursy',route:'courses'},{label:course.title,route:'course',target:course.id},{label:'Teoria i wzory'}])}<header class="quadratic-theory-head"><div><span>KARTA WIEDZY · EGZAMIN ÓSMOKLASISTY</span><h1>${course.title} bez chaosu</h1><p>${spec.lead}</p></div><button class="primary-btn" data-route="xpath" data-target="${first.id}">Przejdź do zadań ${icon('arrow')}</button></header><section class="extra-theory-focus card">${conceptBoard(focus,course.id)}<div class="extra-formula-list">${spec.formulas.map((formula,index)=>`<div><span>${String(index+1).padStart(2,'0')}</span><b>${formula}</b></div>`).join('')}</div></section><section class="quadratic-knowledge-grid">${spec.theory.map(([title,text],index)=>`<details ${index===0?'open':''}><summary>${index+1}. ${title}</summary><p>${text}</p></details>`).join('')}</section><section class="quadratic-formula-strip card">${spec.formulas.map((formula,index)=>`<div><span>WZÓR ${index+1}</span><b>${formula}</b></div>`).join('')}</section></div>`;}

function e8KnowledgePage(){
  const selected=knowledgeState.course&&extraSubjectSpecs[knowledgeState.course]?knowledgeState.course:null;
  if(!selected)return `<div class="page knowledge-page kb-page"><header class="kb-head"><div><div class="eyebrow">${icon('book')} Podręcznik E8</div><h1>Co chcesz zrozumieć?</h1><p>Wybierz dział. W środku znajdziesz czytelny rysunek, wzory, przykłady i przejście do ćwiczeń.</p></div><span>${courses.length} działów</span></header><aside class="kb-cke-strip no-math-format"><div class="kb-cke-mark">CKE</div><div><b>Oficjalne materiały egzaminacyjne</b><span>Zakres panelu porównujemy z bieżącymi informatorami publikowanymi przez CKE.</span></div><a href="https://cke.gov.pl/egzamin-osmoklasisty/informatory/" target="_blank" rel="noopener">Otwórz stronę CKE ↗</a></aside>${knowledgeProgress(1)}<section class="kb-course-grid kb-course-grid-e8" aria-label="Wybierz dział">${courses.map(course=>{const spec=extraSubjectSpecs[course.id],formulaCount=window.E8_TEXTBOOK?.[course.id]?.formulas.length||spec.formulas.length;return `<button class="kb-course kb-course-e8 card" data-open-e8-knowledge="${course.id}" style="--kb:${courseColor(course)}"><div class="kb-course-top"><i>${course.n}</i><span>${spec.theory.length} tematów · ${formulaCount} kart wzorów</span></div><div class="kb-course-copy"><small>KARTA WIEDZY</small><h2>${course.title}</h2><p>${spec.lead}</p></div><div class="kb-course-formula"><small>NA START</small><strong>${spec.formulas[0]}</strong></div><div class="kb-course-footer"><span>Rysunek · wzory · teoria</span><b>Otwórz →</b></div></button>`;}).join('')}</section></div>`;
  const course=courseById(selected),spec=extraSubjectSpecs[selected],first=spec.paths.find(path=>!path.exam)||spec.paths[0],meta=textbookCourseMeta(course.id),focus=textbookFocusConfig(course.id,first.concept),atlas=window.E8_TEXTBOOK?.[course.id]||{formulas:[],skills:[],visuals:[]},example=first.rows?.[0],correct=example?example[1][example[2]]:'',theoryExamples=window.E8_THEORY_EXAMPLES?.[course.id]||textbookTheoryExamples[course.id]||[];
  return `<div class="page knowledge-page kb-page textbook-page" style="--knowledge:${courseColor(course)}">
    <button class="kb-back" data-e8-knowledge-back>← Wszystkie działy</button>${knowledgeProgress(2)}
    <header class="kb-section-hero textbook-hero"><div class="kb-section-index">${course.n}</div><div class="kb-section-copy"><span>PODRĘCZNIK E8 · LEKCJA W 10 MINUT</span><h1>${course.title}</h1><p>${meta.goal}</p></div><div class="kb-section-status"><span>PO TEJ LEKCJI</span><strong>${spec.theory.length} kluczowych tematów</strong><small>Rysunek, metoda, wzory, przykład i szybkie przejście do treningu.</small></div></header>
    <nav class="textbook-lesson-flow" aria-label="Plan lekcji"><a href="#tb-idea" data-textbook-section="tb-idea" class="active"><i>1</i>Zrozum</a><b>→</b><a href="#tb-atlas" data-textbook-section="tb-atlas"><i>2</i>Zobacz</a><b>→</b><a href="#tb-formulas" data-textbook-section="tb-formulas"><i>3</i>Zapamiętaj</a><b>→</b><a href="#tb-example" data-textbook-section="tb-example"><i>4</i>Przećwicz</a></nav>
    <section class="textbook-concept-card card" id="tb-idea"><div class="textbook-section-title"><span>01 · ZROZUM</span><h2>Najważniejsza idea na jednym rysunku</h2></div>${conceptBoard(focus,course.id)}</section>
    <section class="textbook-method"><div class="textbook-section-title"><span>02 · ZRÓB TO SAMODZIELNIE</span><h2>Metoda w 3 krokach</h2><p>Ten schemat możesz przepisać na brudnopis przed rozwiązaniem zadania.</p></div><div class="textbook-method-grid">${meta.method.map((step,index)=>`<article><i>${index+1}</i><div><small>KROK ${index+1}</small><b>${step}</b></div></article>`).join('')}</div></section>
    <section class="textbook-atlas" id="tb-atlas"><div class="textbook-section-title"><span>03 · ATLAS WIZUALNY</span><h2>Każdy temat ma własny rysunek</h2><p>Jedna ilustracja odpowiada jednej serii. Podpis mówi dokładnie, co odczytać i jakiej reguły użyć.</p></div><div class="textbook-visual-grid">${atlas.visuals.map((item,index)=>`<article class="atlas-card"><div class="atlas-visual"><span class="atlas-number">${String(index+1).padStart(2,'0')}</span>${textbookMiniVisual(item.type)}</div><h3>${item.title}</h3><p>${item.caption}</p></article>`).join('')}</div></section>
    <section class="textbook-formulas" id="tb-formulas"><div class="textbook-section-title textbook-title-row"><div><span>04 · BANK WZORÓW I REGUŁ</span><h2>Najważniejsze zapisy w tym dziale</h2><p>Każda karta podaje zastosowanie, warunek albo typową pułapkę.</p></div><b>${atlas.formulas.length} kart</b></div><div class="textbook-formula-grid textbook-formula-grid-full math-content">${atlas.formulas.map((item,index)=>`<article><div><span>${String(index+1).padStart(2,'0')}</span><small>${item.name}</small></div><strong>${item.formula}</strong><p>${item.use}</p></article>`).join('')}</div></section>
    <section class="textbook-skill-check card"><div><span>ZAKRES TEJ LEKCJI</span><h2>Po tej lekcji sprawdź, czy potrafisz:</h2></div><ul>${atlas.skills.map(skill=>`<li><i>✓</i>${skill}</li>`).join('')}</ul></section>
    ${example?`<section class="textbook-example card" id="tb-example"><div class="textbook-example-head"><div><span>05 · PRZYKŁAD Z ROZWIĄZANIEM</span><h2>${first.title}</h2></div><b>typ E8</b></div><div class="textbook-example-question"><small>ZADANIE</small><strong>${example[0]}</strong><div class="textbook-example-options">${example[1].map((answer,index)=>`<span class="${index===example[2]?'correct':''}"><i>${'ABCD'[index]}</i>${answer}</span>`).join('')}</div></div><div class="textbook-example-steps"><article><i>1</i><div><small>ROZPOZNAJ</small><b>${example[3]}</b></div></article><article><i>2</i><div><small>OBLICZ</small><b>${example[4]}</b></div></article><article class="result"><i>✓</i><div><small>ODPOWIEDŹ</small><b>${'ABCD'[example[2]]}. ${correct}</b></div></article></div></section>`:''}
    <aside class="textbook-trap"><span>!</span><div><small>PUŁAPKA EGZAMINACYJNA</small><b>${meta.trap}</b></div></aside>
    <section class="textbook-theory"><div class="textbook-section-title"><span>06 · UPORZĄDKUJ WIEDZĘ</span><h2>Pełne wyjaśnienia z przykładami</h2><p>Każda karta wyjaśnia regułę, pokazuje konkretny rachunek i podpowiada, jak użyć jej na egzaminie.</p></div><div class="textbook-theory-grid">${spec.theory.map(([title,body],index)=>{const detail=theoryExamples[index]||['Przykład krok po kroku','Najpierw nazwij dane, następnie zastosuj regułę i sprawdź wynik.'];return `<article><span>${String(index+1).padStart(2,'0')}</span><div><h3>${title}</h3><p>${body}</p><div class="textbook-theory-example"><small>PRZYKŁAD</small><b>${detail[0]}</b><p>${detail[1]}</p></div></div></article>`;}).join('')}</div></section>
    <section class="kb-practice-link textbook-practice"><div><span>TERAZ TY</span><b>Sprawdź wiedzę w serii 10 przykładów A–D</b><small>Po każdej odpowiedzi zobaczysz wyjaśnienie krok po kroku.</small></div><button class="primary-btn" data-open-e8-path="${course.id}|${first.id}">Rozpocznij trening ${icon('arrow')}</button></section>
  </div>`;
}

function quadraticCoursePage(course){return `<div class="page course-level">${breadcrumb([{label:'Kursy',route:'courses'},{label:'Funkcja kwadratowa'}])}<header class="course-detail-hero quadratic-hero card accent-purple"><div><span>KURS 02 · ŚCIEŻKA CKE</span><h1>Funkcja kwadratowa</h1><p>Od odczytywania paraboli przez przesunięcia i ekstrema aż do parametrów oraz zadań egzaminacyjnych. Zacznij od karty teorii albo wybierz jeden konkretny dział.</p><div class="quadratic-hero-actions"><button class="primary-btn" data-route="qtheory">Otwórz teorię i wzory ${icon('book')}</button><button class="secondary-btn" data-route="qpath" data-target="q-graph">Rozpocznij pierwszy dział</button></div></div><div class="quadratic-hero-score"><strong>${coursePercent(course)}%</strong><span>${courseMasteredCount(course)} z ${course.taskIds.length} elementów opanowanych</span><div class="progress-track"><div class="progress-fill" style="width:${coursePercent(course)}%"></div></div></div></header><div class="section-head"><h2>Wybierz dział</h2><span>Każdy dział otwiera osobną kartę z seriami po 10 przykładów</span></div><section class="path-choice-grid">${quadraticPathways.map(path=>{const done=path.taskIds.filter(id=>(saved.mastery[id]?.best||0)>=80).length,pct=Math.round(done/path.taskIds.length*100);return `<button class="path-choice card accent-${path.accent}" data-open-qpath="${path.id}"><span class="path-choice-number">${path.n}</span><div><small>${path.id==='q-exam'?'SPRAWDZIAN':'DZIAŁ'}</small><h2>${path.title}</h2><p>${path.desc}</p><div class="path-choice-progress"><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><b>${done}/${path.taskIds.length}</b></div></div>${icon('arrow')}</button>`;}).join('')}</section></div>`;}

function quadraticPathPage(){const path=activeQuadraticPath(),done=path.taskIds.filter(id=>(saved.mastery[id]?.best||0)>=80).length,isExam=path.id==='q-exam';return `<div class="page course-level">${breadcrumb([{label:'Kursy',route:'courses'},{label:'Funkcja kwadratowa',route:'course',target:'quadratic'},{label:path.title}])}<header class="level-heading"><div><span>${isExam?'FINAŁ KURSU':`DZIAŁ ${path.n}`} · FUNKCJA KWADRATOWA</span><h1>${path.title}</h1><p>${path.desc}</p></div><div class="level-score"><b>${done}/${path.taskIds.length}</b><small>${isExam?'zadań zaliczonych':'serii opanowanych'}</small></div></header>${isExam?`<section class="exam-path-callout card"><div>${icon('clock')}<span><b>Miniarkusz funkcji kwadratowej</b><small>10 zadań A–D · 25 minut · wspólny wykres · wynik i wyjaśnienia na końcu</small></span></div><button class="primary-btn" data-route="exam" data-target="quadratic">Uruchom sprawdzian ${icon('arrow')}</button></section>`:`<section class="series-grid">${path.taskIds.map((id,index)=>`<article class="series-wrap"><span>${String(index+1).padStart(2,'0')}</span>${taskCard(id,tasks[id])}</article>`).join('')}</section>`}</div>`;}

function quadraticTheoryPage(){return `<div class="page quadratic-theory-page">${breadcrumb([{label:'Kursy',route:'courses'},{label:'Funkcja kwadratowa',route:'course',target:'quadratic'},{label:'Teoria i wzory'}])}<header class="quadratic-theory-head"><div><span>KARTA WIEDZY · ZAKRES CKE</span><h1>Funkcja kwadratowa bez chaosu</h1><p>Najpierw rozpoznaj postać wzoru. Potem wybierz schemat: wykres, zera, przesunięcie, ekstremum albo parametr.</p></div><button class="primary-btn" data-route="qpath" data-target="q-graph">Przejdź do zadań ${icon('arrow')}</button></header><section class="quadratic-theory-focus card"><div class="quadratic-theory-graph">${quadraticGraph({a:1,p:2,q:-3,showRoots:true})}</div><div class="quadratic-theory-formula"><span>POSTAĆ KANONICZNA</span><strong>f(x) = a(x − p)² + q</strong><div><b>W = (p, q)</b><small>wierzchołek paraboli</small></div><div><b>x = p</b><small>oś symetrii</small></div><div><b>a &gt; 0 ↑ · a &lt; 0 ↓</b><small>kierunek ramion</small></div></div></section><section class="quadratic-knowledge-grid"><details open><summary>1. Definicja i wykres</summary><p>Funkcja kwadratowa ma postać <b>f(x) = ax² + bx + c</b>, gdzie <b>a ≠ 0</b>. Jej wykresem jest parabola, a dziedziną jest ℝ. Znak a określa kierunek ramion.</p></details><details><summary>2. Trzy postacie</summary><p>Ogólna: <b>ax² + bx + c</b>. Kanoniczna: <b>a(x − p)² + q</b>. Iloczynowa: <b>a(x − x₁)(x − x₂)</b>, gdy istnieją miejsca zerowe. Każda postać ujawnia inne informacje.</p></details><details><summary>3. Delta, zera i Viète</summary><p><b>Δ = b² − 4ac</b>. Dla Δ &gt; 0 są dwa zera, dla Δ = 0 jedno podwójne, a dla Δ &lt; 0 nie ma zer rzeczywistych. Gdy zera istnieją: <b>x₁+x₂=−b/a</b> oraz <b>x₁x₂=c/a</b>.</p></details><details><summary>4. Wierzchołek</summary><p><b>p = −b/(2a)</b> oraz <b>q = f(p) = −Δ/(4a)</b>. Wierzchołek wyznacza minimum dla a &gt; 0 lub maksimum dla a &lt; 0.</p></details><details><summary>5. Monotoniczność i zbiór wartości</summary><p>Dla a &gt; 0 funkcja maleje do p i rośnie od p, a jej wartości to <b>[q, +∞)</b>. Dla a &lt; 0 kierunki są odwrotne, a zbiorem wartości jest <b>(−∞, q]</b>.</p></details><details><summary>6. Przesunięcia wykresu</summary><p><b>g(x)=f(x−r)+s</b> przesuwa wykres o r w prawo i s w górę. Znak wewnątrz nawiasu działa przeciwnie: <b>f(x+3)</b> oznacza przesunięcie o 3 w lewo.</p></details><details><summary>7. Ekstrema w przedziale</summary><p>Na przedziale domkniętym <b>[u, v]</b> oblicz wartości na obu końcach oraz w wierzchołku, jeśli <b>p∈[u,v]</b>. Najmniejsza i największa z tych wartości dają szukane ekstrema.</p></details><details><summary>8. Parametr i nierówności</summary><p>Warunek z treści zamień na warunek dla <b>a</b>, <b>Δ</b>, wierzchołka albo miejsc zerowych. Nierówność odczytuj z położenia paraboli względem osi x, pamiętając o domknięciu końców dla ≤ lub ≥.</p></details></section><section class="quadratic-formula-strip card"><div><span>WIERZCHOŁEK p</span><b>p = −b/(2a)</b></div><div><span>WIERZCHOŁEK q</span><b>q = −Δ/(4a)</b></div><div><span>DELTA</span><b>Δ = b² − 4ac</b></div><div><span>PIERWIASTKI</span><b>x₁,₂ = (−b ± √Δ)/(2a)</b></div><div><span>VIÈTE · SUMA</span><b>x₁ + x₂ = −b/a</b></div><div><span>VIÈTE · ILOCZYN</span><b>x₁x₂ = c/a</b></div></section></div>`;}

function sequenceCoursePage(course){return `<div class="page course-level">${breadcrumb([{label:'Kursy',route:'courses'},{label:'Ciągi'}])}<header class="course-detail-hero quadratic-hero sequence-hero card accent-green"><div><span>KURS 03 · PEŁNA ŚCIEŻKA</span><h1>Ciągi</h1><p>Od podstawiania indeksu do ciągów geometrycznych, rekurencji i procentu składanego. Zacznij od karty wzorów albo wybierz konkretny dział.</p><div class="quadratic-hero-actions"><button class="primary-btn" data-route="stheory">Otwórz teorię i wzory ${icon('book')}</button><button class="secondary-btn" data-route="spath" data-target="s-basics">Rozpocznij pierwszy dział</button></div></div><div class="quadratic-hero-score sequence-hero-score"><strong>${coursePercent(course)}%</strong><span>${courseMasteredCount(course)} z ${course.taskIds.length} elementów opanowanych</span><div class="progress-track"><div class="progress-fill" style="width:${coursePercent(course)}%"></div></div></div></header><div class="section-head"><h2>Wybierz dział</h2><span>Każdy dział ma własną kartę i dwie serie ćwiczeń</span></div><section class="path-choice-grid">${sequencePathways.map(path=>{const done=path.taskIds.filter(id=>(saved.mastery[id]?.best||0)>=80).length,pct=Math.round(done/path.taskIds.length*100);return `<button class="path-choice card accent-${path.accent}" data-open-spath="${path.id}"><span class="path-choice-number">${path.n}</span><div><small>${path.id==='s-exam'?'SPRAWDZIAN':'DZIAŁ'}</small><h2>${path.title}</h2><p>${path.desc}</p><div class="path-choice-progress"><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><b>${done}/${path.taskIds.length}</b></div></div>${icon('arrow')}</button>`;}).join('')}</section></div>`;}

function sequencePathPage(){const path=activeSequencePath(),done=path.taskIds.filter(id=>(saved.mastery[id]?.best||0)>=80).length,isExam=path.id==='s-exam';return `<div class="page course-level">${breadcrumb([{label:'Kursy',route:'courses'},{label:'Ciągi',route:'course',target:'sequences'},{label:path.title}])}<header class="level-heading"><div><span>${isExam?'FINAŁ KURSU':`DZIAŁ ${path.n}`} · CIĄGI</span><h1>${path.title}</h1><p>${path.desc}</p></div><div class="level-score"><b>${done}/${path.taskIds.length}</b><small>${isExam?'zadań zaliczonych':'serii opanowanych'}</small></div></header>${isExam?`<section class="exam-path-callout card"><div>${icon('clock')}<span><b>Miniarkusz z ciągów</b><small>${path.taskIds.length} zadań A–D · 25 minut · wynik i wyjaśnienia na końcu</small></span></div><button class="primary-btn" data-route="exam" data-target="sequences">Uruchom sprawdzian ${icon('arrow')}</button></section>`:`<section class="series-grid">${path.taskIds.map((id,index)=>`<article class="series-wrap"><span>${String(index+1).padStart(2,'0')}</span>${taskCard(id,tasks[id])}</article>`).join('')}</section>`}</div>`;}

function sequenceTheoryPage(){return `<div class="page quadratic-theory-page sequence-theory-page">${breadcrumb([{label:'Kursy',route:'courses'},{label:'Ciągi',route:'course',target:'sequences'},{label:'Teoria i wzory'}])}<header class="quadratic-theory-head sequence-theory-head"><div><span>KARTA WIEDZY</span><h1>Ciągi krok po kroku</h1><p>Najpierw ustal typ ciągu. Dopiero potem wybierz wzór — dzięki temu nie pomylisz różnicy r z ilorazem q.</p></div><button class="primary-btn" data-route="spath" data-target="s-basics">Przejdź do zadań ${icon('arrow')}</button></header><section class="quadratic-theory-focus sequence-theory-focus card"><div class="quadratic-theory-graph">${sequenceTable({formula:'aₙ = 2 + (n − 1)·3',values:[2,5,8,11,14],change:'+3',note:'Stała różnica r = 3'})}</div><div class="quadratic-theory-formula"><span>CIĄG ARYTMETYCZNY</span><strong>aₙ = a₁ + (n − 1)r</strong><div><b>r = aₙ₊₁ − aₙ</b><small>stała różnica</small></div><div><b>Sₙ = n(a₁ + aₙ)/2</b><small>suma n początkowych wyrazów</small></div><div><b>q = aₙ₊₁/aₙ</b><small>stały iloraz w ciągu geometrycznym</small></div></div></section><section class="quadratic-knowledge-grid sequence-knowledge-grid"><details open><summary>1. Wzór ogólny</summary><p>Wartość <b>aₙ</b> otrzymujesz przez podstawienie indeksu n. Aby sprawdzić, czy liczba jest wyrazem ciągu, rozwiązujesz równanie z niewiadomą n i sprawdzasz, czy n jest dodatnią liczbą całkowitą.</p></details><details><summary>2. Ciąg arytmetyczny</summary><p>Kolejne wyrazy różnią się o stałą liczbę <b>r</b>. Wzór: <b>aₙ = a₁ + (n − 1)r</b>. Dodatnie r oznacza wzrost, ujemne — spadek.</p></details><details><summary>3. Suma arytmetyczna</summary><p><b>Sₙ = n(a₁ + aₙ)/2</b>. To liczba wyrazów pomnożona przez średnią pierwszego i ostatniego wyrazu.</p></details><details><summary>4. Ciąg geometryczny</summary><p>Każdy kolejny wyraz powstaje przez mnożenie przez stały iloraz <b>q</b>. Wzór: <b>aₙ = a₁qⁿ⁻¹</b>.</p></details><details><summary>5. Suma geometryczna</summary><p>Dla <b>q ≠ 1</b>: <b>Sₙ = a₁(1 − qⁿ)/(1 − q)</b>. Gdy q = 1, wszystkie wyrazy są równe i <b>Sₙ = na₁</b>.</p></details><details><summary>6. Rekurencja i procent składany</summary><p>Rekurencja opisuje następny wyraz za pomocą poprzedniego. W procencie składanym kolejne wartości tworzą ciąg geometryczny o ilorazie <b>1 + p/100</b>.</p></details></section><section class="quadratic-formula-strip sequence-formula-strip card"><div><span>ARYTMETYCZNY</span><b>aₙ = a₁ + (n − 1)r</b></div><div><span>SUMA</span><b>Sₙ = n(a₁ + aₙ)/2</b></div><div><span>GEOMETRYCZNY</span><b>aₙ = a₁qⁿ⁻¹</b></div><div><span>PROCENT SKŁADANY</span><b>Kₙ = K₀(1 + p/100)ⁿ</b></div></section></div>`;}

function algebraCoursePage(course){return `<div class="page course-level">${breadcrumb([{label:'Kursy',route:'courses'},{label:'Równania i nierówności'}])}<header class="course-detail-hero quadratic-hero algebra-hero card accent-navy"><div><span>KURS 04 · PEŁNA ŚCIEŻKA CKE</span><h1>Równania i nierówności</h1><p>Od przekształceń równoważnych przez układy i nierówności aż do dziedziny oraz parametru. Każde ćwiczenie pokazuje tok rozwiązania.</p><div class="quadratic-hero-actions"><button class="primary-btn" data-route="knowledge" data-target="equations">Otwórz teorię i reguły ${icon('book')}</button><button class="secondary-btn" data-route="apath" data-target="a-linear">Rozpocznij pierwszy dział</button></div></div><div class="quadratic-hero-score"><strong>${coursePercent(course)}%</strong><span>${courseMasteredCount(course)} z ${course.taskIds.length} elementów opanowanych</span><div class="progress-track"><div class="progress-fill" style="width:${coursePercent(course)}%"></div></div></div></header><div class="section-head"><h2>Wybierz dział</h2><span>6 działów po 2 serie oraz finałowy miniarkusz</span></div><section class="path-choice-grid">${algebraPathways.map(path=>{const done=path.taskIds.filter(id=>(saved.mastery[id]?.best||0)>=80).length,pct=Math.round(done/path.taskIds.length*100);return `<button class="path-choice card accent-${path.accent}" data-open-apath="${path.id}"><span class="path-choice-number">${path.n}</span><div><small>${path.id==='a-exam'?'SPRAWDZIAN':'DZIAŁ'}</small><h2>${path.title}</h2><p>${path.desc}</p><div class="path-choice-progress"><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><b>${done}/${path.taskIds.length}</b></div></div>${icon('arrow')}</button>`;}).join('')}</section></div>`;}
function algebraPathPage(){const path=activeAlgebraPath(),done=path.taskIds.filter(id=>(saved.mastery[id]?.best||0)>=80).length,isExam=path.id==='a-exam';return `<div class="page course-level">${breadcrumb([{label:'Kursy',route:'courses'},{label:'Równania i nierówności',route:'course',target:'equations'},{label:path.title}])}<header class="level-heading"><div><span>${isExam?'FINAŁ KURSU':`DZIAŁ ${path.n}`} · RÓWNANIA</span><h1>${path.title}</h1><p>${path.desc}</p></div><div class="level-score"><b>${done}/${path.taskIds.length}</b><small>${isExam?'zadań zaliczonych':'serii opanowanych'}</small></div></header>${isExam?`<section class="exam-path-callout card"><div>${icon('clock')}<span><b>Miniarkusz równań i nierówności</b><small>10 zadań A–D · 25 minut · pełne wyjaśnienia na końcu</small></span></div><button class="primary-btn" data-route="exam" data-target="equations">Uruchom sprawdzian ${icon('arrow')}</button></section>`:`<section class="series-grid">${path.taskIds.map((id,index)=>`<article class="series-wrap"><span>${String(index+1).padStart(2,'0')}</span>${taskCard(id,tasks[id])}</article>`).join('')}</section>`}</div>`;}
function algebraTheoryPage(){return `<div class="page quadratic-theory-page algebra-theory-page">${breadcrumb([{label:'Kursy',route:'courses'},{label:'Równania i nierówności',route:'course',target:'equations'},{label:'Teoria i reguły'}])}<header class="quadratic-theory-head"><div><span>KARTA WIEDZY</span><h1>Reguły, które prowadzą do wyniku</h1><p>Nie uczysz się zgadywać odpowiedzi. Widzisz, jaka operacja została wykonana i dlaczego nie zmienia zbioru rozwiązań.</p></div><button class="primary-btn" data-route="apath" data-target="a-linear">Przejdź do zadań ${icon('arrow')}</button></header><section class="algebra-theory-demo card">${algebraBoard({label:'PRZEKSZTAŁCENIA RÓWNOWAŻNE',lines:['3x + 5 = 17','3x = 12','x = 4'],rule:'Od obu stron odejmujemy 5, a potem obie strony dzielimy przez 3.'})}</section><section class="quadratic-knowledge-grid"><details open><summary>1. Równania liniowe</summary><p>Dodawaj, odejmuj, mnóż lub dziel obie strony przez tę samą liczbę różną od zera. Celem jest postać <b>x = liczba</b>.</p></details><details><summary>2. Układy równań</summary><p>Metoda podstawiania lub eliminacji prowadzi do punktu wspólnego prostych. Układ może mieć jedno, zero albo nieskończenie wiele rozwiązań.</p></details><details><summary>3. Równania kwadratowe i iloczynowe</summary><p>Użyj delty albo rozkładu na czynniki. Iloczyn jest zerem, gdy przynajmniej jeden czynnik jest zerem.</p></details><details><summary>4. Nierówności</summary><p>Przy mnożeniu lub dzieleniu przez liczbę ujemną odwracasz znak. Dla trójmianu odczytujesz znak z paraboli i miejsc zerowych.</p></details><details><summary>5. Dziedzina i równania wymierne</summary><p>Najpierw wyklucz zera mianownika. Po rozwiązaniu równania sprawdź, czy wynik należy do dziedziny.</p></details><details><summary>6. Parametr</summary><p>Rozpatruj przypadki. Dla równania kwadratowego liczba rozwiązań zależy od znaku delty, a dla liniowego od współczynnika przy x.</p></details></section><section class="quadratic-formula-strip card"><div><span>KWADRATOWE</span><b>Δ = b² − 4ac</b></div><div><span>ILOCZYN</span><b>A·B = 0</b></div><div><span>MIANOWNIK</span><b>M(x) ≠ 0</b></div><div><span>JEDEN PIERWIASTEK</span><b>Δ = 0</b></div></section></div>`;}

function practice(){return `<div class="page course-level">${breadcrumb([{label:'Kursy',route:'courses'},{label:'Funkcja liniowa'}])}<header class="level-heading"><div><span>KURS: FUNKCJA LINIOWA · WYBIERZ DZIAŁ</span><h1>Wybierz dział</h1><p>Na kolejnym ekranie zobaczysz tylko serie dotyczące wybranej umiejętności.</p></div><div class="level-score"><b>${completionPercent()}%</b><small>całego kursu</small></div></header><section class="path-choice-grid">${pathways.map(path=>{const done=path.taskIds.filter(id=>(saved.mastery[id]?.best||0)>=80).length,pct=Math.round(done/path.taskIds.length*100);return `<button class="path-choice card accent-${path.accent}" data-open-path="${path.id}"><span class="path-choice-number">${path.n}</span><div><small>${path.id==='exam'?'SPRAWDZIAN':'DZIAŁ'}</small><h2>${path.title}</h2><p>${path.desc}</p><div class="path-choice-progress"><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><b>${done}/${path.taskIds.length}</b></div></div>${icon('arrow')}</button>`;}).join('')}</section></div>`;}

function pathPage(){const path=activePath(),done=path.taskIds.filter(id=>(saved.mastery[id]?.best||0)>=80).length;return `<div class="page course-level">${breadcrumb([{label:'Kursy',route:'courses'},{label:'Funkcja liniowa',route:'practice'},{label:path.title}])}<header class="level-heading"><div><span>DZIAŁ ${path.n} · WYBIERZ SERIĘ</span><h1>${path.title}</h1><p>${path.desc}</p></div><div class="level-score"><b>${done}/${path.taskIds.length}</b><small>serii opanowanych</small></div></header>${path.id==='exam'?`<section class="exam-path-callout card"><div>${icon('clock')}<span><b>Gotowy na próbę samodzielną?</b><small>${path.taskIds.length} zadań A–D · 25 minut · wynik na końcu</small></span></div><button class="primary-btn" data-route="exam" data-target="linear">Uruchom sprawdzian CKE ${icon('arrow')}</button></section>`:''}<section class="series-grid">${path.taskIds.map((id,index)=>`<article class="series-wrap"><span>${String(index+1).padStart(2,'0')}</span>${taskCard(id,tasks[id])}</article>`).join('')}</section></div>`;}

const theorySections=['Czym jest funkcja?','Wzór y = ax + b','Współczynnik a','Wyraz wolny b','Miejsce zerowe','Położenie prostych','Podsumowanie'];
const theoryChecks=[
  {q:'Które zdanie poprawnie opisuje funkcję?',options:['Jednemu x można przypisać dwie różne wartości y','Każdej wartości x przypisujemy dokładnie jedną wartość y','Każda funkcja musi przechodzić przez punkt (0, 0)','Funkcja zawsze ma miejsce zerowe'],correct:1,hint:'Skup się na słowach „każdej liczbie x” oraz „dokładnie jedną”.',conclusion:'Funkcja każdemu argumentowi x przypisuje dokładnie jedną wartość y.'},
  {q:'Dla funkcji y = −2x + 3 wskaż współczynniki a i b.',options:['a = 3, b = −2','a = −2, b = 3','a = 2, b = −3','a = −2, b = −3'],correct:1,hint:'Współczynnik a stoi bezpośrednio przy x, a b jest liczbą bez x.',conclusion:'W zapisie y = ax + b liczba przy x to a, a liczba bez x to b.'},
  {q:'Co możesz powiedzieć o funkcji, gdy a < 0?',options:['Jest rosnąca','Jest stała','Jest malejąca','Nie ma wykresu'],correct:2,hint:'Idąc po wykresie w prawo, jego wysokość wtedy maleje.',conclusion:'Gdy a < 0, funkcja jest malejąca; gdy a > 0 — rosnąca.'},
  {q:'W którym punkcie wykres y = ax + b przecina oś y?',options:['(b, 0)','(0, b)','(a, b)','(0, a)'],correct:1,hint:'Na osi y współrzędna x zawsze jest równa 0.',conclusion:'Wyraz wolny b wskazuje punkt przecięcia z osią y: (0, b).' },
  {q:'Co podstawiamy za y, gdy szukamy miejsca zerowego?',options:['y = 0','y = 1','y = b','y = a'],correct:0,hint:'Miejsce zerowe leży na osi x, a każdy punkt tej osi ma wysokość 0.',conclusion:'Miejsce zerowe wyznaczamy z warunku y = 0; dla a ≠ 0 mamy x₀ = −b/a.'},
  {q:'Jaki warunek spełniają dwie różne proste równoległe?',options:['a₁ · a₂ = −1','a₁ = a₂','b₁ = b₂','a₁ + a₂ = 0'],correct:1,hint:'Proste równoległe mają dokładnie takie samo nachylenie.',conclusion:'Dwie różne proste są równoległe, gdy mają równe współczynniki kierunkowe a.'}
];

function theoryCheckpoint(p){
  if(p>=theoryChecks.length)return '';
  const check=theoryChecks[p],done=saved.theoryChecks.includes(p);
  return `<section class="theory-checkpoint ${done?'completed':''}" id="theoryCheckpoint"><div class="checkpoint-head"><div><span>${done?'WNIOSEK ZAPISANY':'SPRAWDŹ, CZY ROZUMIESZ'}</span><h3>${check.q}</h3></div><i>${done?'✓':'?'}</i></div><div class="checkpoint-options">${check.options.map((option,i)=>`<button class="answer checkpoint-answer ${done&&i===check.correct?'correct':''}" data-theory-answer="${i}" ${done?'disabled':''}><i class="answer-letter">${'ABCD'[i]}</i><span>${option}</span></button>`).join('')}</div><div class="checkpoint-feedback ${done?'correct':''}" role="status" aria-live="polite">${done?`<b>Twój wniosek:</b> ${check.conclusion}`:'Wybierz odpowiedź A, B, C albo D. Jeśli nie masz pewności, skorzystaj z małej podpowiedzi.'}</div>${done?'':`<button class="checkpoint-hint" id="theoryHintButton">${icon('light')} Mała podpowiedź</button>`}</section>`;
}

function theoryNotebook(){return `<section class="learning-notebook"><div class="notebook-head"><div>${icon('brain')}</div><span><b>Twoja karta wniosków</b><small>Zbudowana z odpowiedzi udzielonych podczas lekcji</small></span><strong>${saved.theoryChecks.length} / ${theoryChecks.length}</strong></div><div class="notebook-list">${theoryChecks.map((check,i)=>`<div class="notebook-item ${saved.theoryChecks.includes(i)?'done':''}"><i>${saved.theoryChecks.includes(i)?'✓':i+1}</i><span>${saved.theoryChecks.includes(i)?check.conclusion:'Wniosek jeszcze nieodkryty'}</span></div>`).join('')}</div></section>`;}

function theory(){
  const p=state.theoryPage;
  const last=theorySections.length-1,unlocked=Math.min(last,saved.theoryChecks.length),canContinue=p===last||saved.theoryChecks.includes(p),progress=Math.round(saved.theoryChecks.length/theoryChecks.length*100);
  return `<div class="page theory-page"><div class="page-head"><div><div class="eyebrow">${icon('book')} Funkcja liniowa · teoria interaktywna</div><h1>${theorySections[p]}</h1><p>Ekran ${p+1} z ${theorySections.length} · każdy symbol jest połączony z wykresem.</p></div><button class="secondary-btn" data-route="overview">Zapisz i wyjdź</button></div>
  <div class="theory-layout"><aside class="theory-outline card"><div class="theory-progress"><span>Wnioski zapisane</span><strong>${progress}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${progress}%"></div></div><div class="theory-nav">${theorySections.map((name,i)=>`<button class="theory-nav-item ${saved.theoryChecks.includes(i)?'done ':''}${i===p?'active ':''}${i>unlocked?'locked':''}" data-theory-step="${i}" ${i>unlocked?'disabled':''}><i>${saved.theoryChecks.includes(i)?'✓':i>unlocked?'·':i+1}</i><span>${name}</span></button>`).join('')}</div></aside>
  <section class="theory-stage card">${theoryContent(p)}${theoryCheckpoint(p)}<div class="theory-actions"><button class="secondary-btn" id="theoryPrev" ${p===0?'disabled':''}>← Wstecz</button><span>${canContinue?'Możesz przejść dalej':'Najpierw odpowiedz na pytanie'}</span><button class="primary-btn" id="theoryNext" ${canContinue?'':'disabled'}>${p===last?'Przejdź do zadań':'Dalej'} ${icon('arrow')}</button></div></section></div></div>`;
}

function theoryContent(p){
  if(p===0)return `<div class="concept-grid"><div class="concept-copy"><span class="lesson-badge">DEFINICJA</span><h2>Funkcja przypisuje każdej liczbie <span class="math-accent x-color">x</span> dokładnie jedną liczbę <span class="math-accent y-color">y</span>.</h2><p>Możesz myśleć o niej jak o maszynie: wkładasz argument <b>x</b>, wykonujesz działanie opisane wzorem i otrzymujesz wartość <b>y</b>.</p><div class="definition-box"><b>Funkcja liniowa</b><span>to funkcja opisana wzorem</span><strong>f(x) = ax + b</strong><small>gdzie a i b są liczbami rzeczywistymi</small></div></div><div class="concept-visual"><div class="machine"><div class="machine-title">f(x) = 2x + 1</div>${[[-1,-1],[0,1],[2,5]].map(([x,y],i)=>`<div class="machine-row" style="animation-delay:${i*.22}s"><span class="input-pill">x = ${x}</span><i>× 2 + 1</i><span class="output-pill">y = ${y}</span></div>`).join('')}</div><div class="micro-note">Każdy punkt <b>(x, y)</b> z tabeli trafia na jeden wspólny wykres.</div></div></div>`;
  if(p===1)return `<div class="formula-lesson"><span class="lesson-badge">WZÓR OGÓLNY</span><div class="formula-hero"><span class="formula-y">y</span><span>=</span><span class="formula-a">a</span><span class="formula-x">x</span><span>+</span><span class="formula-b">b</span></div><div class="formula-labels"><div><i class="formula-a-bg">a</i><b>kierunek</b><span>obraca prostą i mówi, czy funkcja rośnie</span></div><div><i class="formula-x-bg">x</i><b>argument</b><span>liczba, którą wybierasz na osi poziomej</span></div><div><i class="formula-b-bg">b</i><b>start</b><span>punkt przecięcia wykresu z osią y</span></div></div><div class="concept-grid formula-example"><div class="concept-copy"><h2>Przykład: <span class="math">y = 2x + 1</span></h2><p>Prosta rośnie, bo <b>a = 2 &gt; 0</b>. Przecina oś pionową na wysokości <b>b = 1</b>.</p><div class="legend-line"><span class="dot blue"></span><b>a = 2</b> — wzrost o 2, gdy x rośnie o 1</div><div class="legend-line"><span class="dot pink"></span><b>b = 1</b> — punkt (0, 1)</div></div><div class="graph-wrap">${theoryGraph(2,1)}</div></div></div>`;
  if(p===2)return `<div class="concept-grid interactive-concept"><div class="concept-copy"><span class="lesson-badge">WSPÓŁCZYNNIK KIERUNKOWY</span><h2><span class="formula-a">a</span> decyduje o nachyleniu i monotoniczności</h2><p>Przesuń suwak. Wzór, wykres i trójkąt nachylenia zmienią się jednocześnie.</p><div class="live-formula" id="liveFormula">y = <b>${fmt(state.theoryA)}</b>x + 1</div><label class="big-slider"><span>Wartość a</span><strong id="theoryAValue">${fmt(state.theoryA)}</strong><input id="theoryASlider" type="range" min="-3" max="3" step="0.5" value="${state.theoryA}"></label><div class="insight-box" id="lessonInsight">${aInsight(state.theoryA)}</div></div><div><div class="graph-wrap large-graph" id="theoryGraph">${theoryGraph(state.theoryA,1,false,null,true)}</div><div class="axis-key"><span><i class="horizontal-key"></i><b>Δx = 1</b> — krok w prawo</span><span><i class="vertical-key"></i><b>Δy = ${state.theoryA>=0?'+':''}${fmt(state.theoryA)}</b> — zmiana wysokości</span></div></div></div>`;
  if(p===3)return `<div class="concept-grid interactive-concept"><div class="concept-copy"><span class="lesson-badge">WYRAZ WOLNY</span><h2><span class="formula-b">b</span> przesuwa prostą w górę lub w dół</h2><p>Nachylenie pozostaje takie samo. Zmienia się tylko wysokość przecięcia z osią y.</p><div class="live-formula" id="liveFormula">y = x ${signed(state.theoryB)}</div><label class="big-slider pink-slider"><span>Wartość b</span><strong id="theoryBValue">${fmt(state.theoryB)}</strong><input id="theoryBSlider" type="range" min="-4" max="4" step="1" value="${state.theoryB}"></label><div class="insight-box pink-insight" id="lessonInsight">Wykres przecina oś y w punkcie <b>(0, ${fmt(state.theoryB)})</b>.</div></div><div><div class="graph-wrap large-graph" id="theoryGraph">${theoryGraph(1,state.theoryB)}</div><div class="graph-signature"><span class="dot pink"></span>zaznaczony punkt ma współrzędne <b>(0, b)</b></div></div></div>`;
  if(p===4)return `<div class="concept-grid zero-concept"><div class="concept-copy"><span class="lesson-badge">MIEJSCE ZEROWE</span><h2>To argument, dla którego wykres przecina oś x</h2><p>Na osi x wysokość zawsze wynosi <b>y = 0</b>. Dlatego we wzorze funkcji wstawiamy zero.</p><button class="primary-btn play-equation" id="playEquation">${icon('arrow')} Uruchom wyprowadzenie wzoru</button><div class="equation-stack" id="equationStack"><div><small>1 · warunek</small><strong>0 = ax + b</strong></div><div><small>2 · odejmij b</small><strong>−b = ax</strong></div><div><small>3 · podziel przez a</small><strong>x₀ = −b / a</strong></div></div><div class="case-note"><b>Uwaga:</b> wzór działa dla <span class="math">a ≠ 0</span>. Gdy <span class="math">a = 0</span>, funkcja jest stała.</div></div><div><div class="graph-wrap large-graph">${theoryGraph(1,-2,true)}</div><div class="visual-note">Dla <b>y = x − 2</b> wykres przecina oś x w punkcie <b>(2, 0)</b>, więc x₀ = 2.</div></div></div>`;
  if(p===5)return `<div class="concept-grid interactive-concept"><div class="concept-copy"><span class="lesson-badge">PROSTE</span><h2>Porównuj współczynniki kierunkowe</h2><div class="mode-switch"><button class="${state.lineMode==='parallel'?'active':''}" data-line-mode="parallel">Równoległe</button><button class="${state.lineMode==='perpendicular'?'active':''}" data-line-mode="perpendicular">Prostopadłe</button></div>${state.lineMode==='parallel'?`<div class="relation-rule"><strong>a₁ = a₂</strong><p>Proste mają identyczne nachylenie i nigdy się nie przecinają, jeśli mają różne b.</p><span>Przykład: y = 2x + 1 oraz y = 2x − 3</span></div>`:`<div class="relation-rule"><strong>a₁ · a₂ = −1</strong><p>Współczynniki są przeciwne i odwrotne.</p><span>Przykład: y = 2x + 1 oraz y = −½x − 2</span></div>`}</div><div><div class="graph-wrap large-graph" id="theoryGraph">${relationGraph(state.lineMode)}</div><div class="graph-signature"><span class="dot blue"></span>prosta k <span class="dot pink"></span>prosta l</div></div></div>`;
  return `<div class="summary-lesson"><span class="lesson-badge">KARTA WIEDZY</span><h2>Funkcja liniowa — wszystko na jednej stronie</h2><div class="formula-summary"><article><span>Wzór</span><strong>f(x) = ax + b</strong><p>a, b ∈ ℝ</p></article><article><span>Dziedzina</span><strong>D = ℝ</strong><p>argumentem może być każda liczba rzeczywista</p></article><article><span>Zbiór wartości</span><strong>W = ℝ</strong><p>gdy a ≠ 0; dla a = 0: W = {b}</p></article><article><span>Miejsce zerowe</span><strong>x₀ = −b/a</strong><p>dla a ≠ 0</p></article><article><span>Monotoniczność</span><strong>a &gt; 0 ↗ · a &lt; 0 ↘</strong><p>a = 0 — funkcja stała</p></article><article><span>Przecięcie osi y</span><strong>(0, b)</strong><p>odczytujesz bez liczenia</p></article><article><span>Równoległość</span><strong>a₁ = a₂</strong><p>takie samo nachylenie</p></article><article><span>Prostopadłość</span><strong>a₁a₂ = −1</strong><p>dla prostych niepionowych</p></article></div>${theoryNotebook()}<div class="ready-banner"><div>${icon('check')}</div><span><b>Teoria gotowa.</b> Teraz wykorzystaj każdy wzór w zadaniu z parametrem.</span></div></div>`;
}

function fmt(n){return Number.isInteger(Number(n))?String(Number(n)):Number(n).toFixed(1).replace('.',',');}
function signed(n){return n<0?`− ${Math.abs(n)}`:`+ ${n}`;}
function aInsight(a){if(a>0)return '<b>a &gt; 0</b> — funkcja jest rosnąca. Idąc w prawo, wykres idzie w górę.';if(a<0)return '<b>a &lt; 0</b> — funkcja jest malejąca. Idąc w prawo, wykres opada.';return '<b>a = 0</b> — wykres jest poziomy, więc funkcja jest stała.';}
function graphTicks(originX=140,originY=140){return `<g class="tick-labels">${[-4,-2,2,4].map(v=>`<text x="${originX+v*20}" y="${originY+16}" text-anchor="middle">${v}</text>`).join('')}${[-4,-2,2,4].map(v=>`<text x="${originX-10}" y="${originY-v*20+4}" text-anchor="end">${v}</text>`).join('')}<text x="${originX-8}" y="${originY+16}" text-anchor="end">0</text></g>`;}
function pointLabel(x,y,text,kind='blue',side='right'){const width=Math.max(38,text.length*5+11),left=side==='left'?x-width-8:x+8,top=y-21;return `<g class="point-label ${kind}"><rect x="${left}" y="${top}" width="${width}" height="17" rx="5"/><text x="${left+width/2}" y="${top+11.5}" text-anchor="middle">${text}</text></g>`;}
function theoryGraph(a,b,showZero=false,second=null,showSlope=false){
  if(window.E8_TASK_VISUALS?.linear)return window.E8_TASK_VISUALS.linear({a,b,second,showZero,showSlope});
  const line=(slope,intercept,klass='graph-line')=>{const pts=[];for(let x=-6;x<=6;x+=.2){const y=slope*x+intercept;pts.push(`${(140+x*20).toFixed(1)},${(140-y*20).toFixed(1)}`);}return `<polyline class="${klass}" clip-path="url(#theoryClip)" points="${pts.join(' ')}"/>`;};
  const x0=a!==0?-b/a:null,interceptY=140-b*20,interceptVisible=Math.abs(b)<=5;
  const zeroX=x0!==null?140+x0*20:null,labelsClose=x0!==null&&Math.abs(zeroX-140)<42&&Math.abs(interceptY-140)<42;
  let slope='';
  if(showSlope){const dx=a===0?42:Math.min(42,62/Math.abs(a)),dy=a*dx,x1=140,y1=interceptY,x2=x1+dx,y2=y1-dy;slope=`<g class="slope-triangle"><path d="M${x1} ${y1}H${x2}V${y2}"/><circle cx="${x2}" cy="${y2}" r="3"/><text x="${x1+dx/2}" y="${y1+15}" text-anchor="middle">Δx = 1</text><text x="${x2+8}" y="${(y1+y2)/2+4}">Δy = ${fmt(a)}</text></g>`;}
  return `<svg class="graph-svg teaching-graph" viewBox="0 0 280 280" role="img" aria-label="Podpisany wykres funkcji liniowej y równa się ${fmt(a)} x ${signed(b)}"><defs><clipPath id="theoryClip"><rect x="20" y="20" width="240" height="240" rx="8"/></clipPath><marker id="axisArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0 0 10 5 0 10z"/></marker></defs><rect class="plot-bg" x="20" y="20" width="240" height="240" rx="8"/><g class="graph-grid">${gridSvg()}</g>${graphTicks()}<path class="graph-axis" marker-end="url(#axisArrow)" d="M20 140H260"/><path class="graph-axis" marker-end="url(#axisArrow)" d="M140 260V20"/>${line(a,b)}${second?line(second.a,second.b,'graph-line secondary'):''}${slope}${interceptVisible?`<circle class="point-halo intercept-halo" cx="140" cy="${interceptY}" r="7"/><circle class="intercept-point" cx="140" cy="${interceptY}" r="3.8"/>${pointLabel(140,interceptY,`(0, ${fmt(b)})`,'pink','right')}`:''}${showZero&&x0!==null&&Math.abs(x0)<=5?`<circle class="point-halo zero-halo" cx="${zeroX}" cy="140" r="7"/><circle class="zero-point" cx="${zeroX}" cy="140" r="3.8"/>${pointLabel(zeroX,labelsClose?176:140,`x₀ = ${fmt(x0)}`,'green',labelsClose||x0<=0?'left':'right')}`:''}<text class="axis-title" x="250" y="130">x</text><text class="axis-title" x="149" y="32">y</text></svg>`;}
function relationGraph(mode){return mode==='parallel'?theoryGraph(2,1,false,{a:2,b:-3}):theoryGraph(2,1,false,{a:-.5,b:-2});}

function goTheoryPage(next){const unlocked=Math.min(theorySections.length-1,saved.theoryChecks.length);state.theoryPage=Math.max(0,Math.min(unlocked,next));state.theoryHintFor=null;saved.linearTheory=Math.max(saved.linearTheory,state.theoryPage);persist();render();window.scrollTo({top:0,behavior:'smooth'});}
function bindTheory(){
  $$('[data-theory-step]').forEach(b=>b.addEventListener('click',()=>goTheoryPage(Number(b.dataset.theoryStep))));
  $('#theoryPrev')?.addEventListener('click',()=>goTheoryPage(state.theoryPage-1));
  $('#theoryNext')?.addEventListener('click',()=>{if(state.theoryPage===theorySections.length-1){routeTo('learn','linear');}else goTheoryPage(state.theoryPage+1);});
  $$('[data-theory-answer]').forEach(btn=>btn.addEventListener('click',()=>{const p=state.theoryPage,check=theoryChecks[p];if(!check||saved.theoryChecks.includes(p))return;const picked=Number(btn.dataset.theoryAnswer),box=$('#theoryCheckpoint'),feedback=$('.checkpoint-feedback');if(picked===check.correct){playFeedbackTone('correct');btn.classList.add('correct');box.classList.add('checkpoint-success');saved.theoryChecks.push(p);saved.theoryChecks.sort((a,b)=>a-b);saved.linearTheory=Math.max(saved.linearTheory,p+1);state.theoryHintFor=null;persist();setTimeout(()=>{render();$('#theoryCheckpoint')?.scrollIntoView({behavior:'smooth',block:'center'});},430);}else{playFeedbackTone('wrong');btn.classList.add('wrong');box.classList.remove('checkpoint-error');requestAnimationFrame(()=>box.classList.add('checkpoint-error'));feedback.innerHTML='<b>Sprawdź ten wybór.</b> '+wrongChoiceFeedback(check,picked);feedback.className='checkpoint-feedback wrong';setTimeout(()=>{btn.classList.remove('wrong');box.classList.remove('checkpoint-error');},700);}}));
  $('#theoryHintButton')?.addEventListener('click',()=>{const check=theoryChecks[state.theoryPage],feedback=$('.checkpoint-feedback');state.theoryHintFor=state.theoryPage;feedback.innerHTML=`<b>Podpowiedź:</b> ${check.hint}`;feedback.className='checkpoint-feedback hint';});
  $('#theoryASlider')?.addEventListener('input',e=>{state.theoryA=Number(e.target.value);$('#theoryAValue').textContent=fmt(state.theoryA);$('#liveFormula').innerHTML=`y = <b>${fmt(state.theoryA)}</b>x + 1`;$('#theoryGraph').innerHTML=theoryGraph(state.theoryA,1,false,null,true);$('#theoryGraph').classList.remove('graph-updated');requestAnimationFrame(()=>$('#theoryGraph').classList.add('graph-updated'));$('#lessonInsight').innerHTML=aInsight(state.theoryA);const keys=$$('.axis-key b');if(keys[1])keys[1].textContent=`Δy = ${state.theoryA>=0?'+':''}${fmt(state.theoryA)}`;});
  $('#theoryBSlider')?.addEventListener('input',e=>{state.theoryB=Number(e.target.value);$('#theoryBValue').textContent=fmt(state.theoryB);$('#liveFormula').textContent=`y = x ${signed(state.theoryB)}`;$('#theoryGraph').innerHTML=theoryGraph(1,state.theoryB);$('#lessonInsight').innerHTML=`Wykres przecina oś y w punkcie <b>(0, ${fmt(state.theoryB)})</b>.`;});
  $('#playEquation')?.addEventListener('click',()=>{$('#equationStack').classList.remove('revealed');requestAnimationFrame(()=>$('#equationStack').classList.add('revealed'));});
  $$('[data-line-mode]').forEach(b=>b.addEventListener('click',()=>{state.lineMode=b.dataset.lineMode;render();}));
}

function learn(){const t=tasks[state.task],isLinear=!t.course||t.course==='linear',isQuadratic=t.course==='quadratic',isSequence=t.course==='sequences',isAlgebra=t.course==='equations',course=courseById(t.course||'linear'),path=isLinear?activePath():isQuadratic?(quadraticPathways.find(item=>item.id===t.path)||activeQuadraticPath()):isSequence?(sequencePathways.find(item=>item.id===t.path)||activeSequencePath()):isAlgebra?(algebraPathways.find(item=>item.id===t.path)||activeAlgebraPath()):null,steps=lessonSteps(t),step=steps[state.step],done=Math.min(state.step,steps.length),pct=Math.round(done/steps.length*100),last=state.step>0?steps[state.step-1]:null,solved=state.answers.filter(Boolean).length,crumbs=isLinear?[{label:'Kursy',route:'courses'},{label:'Funkcja liniowa',route:'practice'},{label:path.title,route:'path',target:path.id},{label:t.title}]:isQuadratic?[{label:'Kursy',route:'courses'},{label:'Funkcja kwadratowa',route:'course',target:'quadratic'},{label:path.title,route:'qpath',target:path.id},{label:t.title}]:isSequence?[{label:'Kursy',route:'courses'},{label:'Ciągi',route:'course',target:'sequences'},{label:path.title,route:'spath',target:path.id},{label:t.title}]:isAlgebra?[{label:'Kursy',route:'courses'},{label:'Równania i nierówności',route:'course',target:'equations'},{label:path.title,route:'apath',target:path.id},{label:t.title}]:[{label:'Kursy',route:'courses'},{label:course.title,route:'course',target:course.id},{label:t.title}],backRoute=isLinear?'path':isQuadratic?'qpath':isSequence?'spath':isAlgebra?'apath':'course',backTarget=path?path.id:course.id,context=path?path.title:course.title;return `<div class="page learning-page focus-learning">${breadcrumb(crumbs)}<header class="lesson-bar"><button class="secondary-btn" data-route="${backRoute}" data-target="${backTarget}">← Serie</button><div><span>SERIA · ${context}</span><h1>${t.title}</h1></div><strong>${state.step<steps.length?`Przykład ${state.step+1} / ${steps.length}`:'Seria ukończona'}</strong></header>${state.step<steps.length?`${trainingBrief(t)}${trainingMethodDisclosure(t,step)}`:''}<div class="learn-layout"><div class="visual-column">${visualPanel(t)}<section class="lesson-progress card"><div><span>Twój postęp</span><strong>${solved} poprawnych · ${state.skippedSteps.length} odłożonych</strong></div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><div class="lesson-dots" aria-label="Postęp przez 10 przykładów">${steps.map((_,i)=>`<i class="${state.skippedSteps.includes(i)?'skipped':i<state.step?'done':i===state.step?'active':''}" title="Przykład ${i+1}"></i>`).join('')}</div></section>${last?`<section class="last-conclusion card"><span>${state.skippedSteps.includes(state.step-1)?icon('refresh'):icon('check')} Wyjaśnienie poprzedniego przykładu</span><p>${last.conclusion}</p></section>`:''}</div><section class="lesson-center">${state.step<steps.length?`<article class="focus-task training-question-card card">${questionCard(step,steps.length)}</article>`:successCard(t)}</section></div></div>`;}

function historyCard(step,answer,i){return `<article class="history-step card"><div class="history-label">${icon('check')} Krok ${i+1} zapisany</div><p class="history-question">${step.q}</p><span class="history-answer">${icon('check')} ${answer}</span><div class="conclusion"><b>Wniosek:</b> ${step.conclusion}</div></article>`;}
function shuffledOptions(step){if(!state.optionOrder){state.optionOrder=[...step.options.keys()].sort(()=>Math.random()-.5);}return state.optionOrder;}
function taskText(t,step){return `${t?.topic||''} ${t?.title||''} ${t?.problem||''} ${step?.q||''} ${(step?.hints||[]).join(' ')}`.toLocaleLowerCase('pl');}
function ckeCompetency(t,step){
  const text=taskText(t,step);
  if(/wykres|tabel|punkt|oś|osi|współrzęd|odczyt|reprezentac/.test(text))return{code:'III',label:'Reprezentacje'};
  if(/uzasad|wykaż|udowod|warunek|dlaczego|wniosek|argument/.test(text))return{code:'IV',label:'Rozumowanie'};
  if(/oblicz|wyznacz|rozwiąż|wartość|delta|pierwiast|równanie|nierówność/.test(text))return{code:'I',label:'Sprawność rachunkowa'};
  return{code:'II',label:'Informacje'};
}
function errorInsight(t,step){
  const text=taskText(t,step);
  if(/kolejnoś|nawias|najpierw.*mnoż|najpierw.*dziel|potęg.*mnoż|mnoż.*dodaw|mnoż.*odejm|dziel.*dodaw|dziel.*odejm|[+−-]\s*\d+\s*[·×*:]|[·×*:]\s*\d+\s*[+−-]/.test(text))return{code:'CALC_ORDER',label:'Kolejność działań',tip:'Zapisz kolejność: nawiasy, potęgi, mnożenie i dzielenie, dodawanie i odejmowanie.',next:'Krótki przykład z tym samym układem działań.'};
  if(/ułam|licznik|mianownik|wspóln.*mian|skrac|rozszerz/.test(text))return{code:'FRACTION',label:'Ułamki i proporcje',tip:'Najpierw sprawdź mianowniki i dopiero potem wykonaj działanie.',next:'Podobny przykład z innymi liczbami i tym samym schematem.'};
  if(/proporcj|skala|stosunek|wprost proporc/.test(text))return{code:'RATIO',label:'Proporcje i skala',tip:'Ustaw odpowiadające sobie wielkości w tej samej kolejności i sprawdź jednostki.',next:'Zadanie utrwalające stały stosunek lub skalę.'};
  if(/jednost|cm|mm|km|metr|litr|kilogram|przelicz/.test(text))return{code:'UNIT',label:'Jednostki',tip:'Sprowadź wszystkie dane do jednej jednostki przed rozpoczęciem obliczeń.',next:'Krótka konwersja jednostek w podobnym kontekście.'};
  if(/znak|ujem|nierówno|malej|rosną|większ|mniejsz/.test(text))return{code:'SIGN',label:'Znaki i nierówności',tip:'Sprawdź znak każdej liczby i kierunek nierówności.',next:'Przykład, w którym o wyniku decyduje znak lub zwrot nierówności.'};
  if(/delta|miejsce zer|równani.*kwadrat|rozwiązani/.test(text))return{code:'PROCEDURE',label:'Dobór procedury',tip:'Nazwij metodę przed rozpoczęciem obliczeń.',next:'Zadanie wymagające ponownego wyboru właściwej metody.'};
  if(/potęg|wykładnik/.test(text))return{code:'POWER_RULES',label:'Prawa działań na potęgach',tip:'Przy mnożeniu potęg o tej samej podstawie dodaj wykładniki, a przy dzieleniu je odejmij.',next:'Kolejny przykład wymagający rozpoznania podstawy i właściwego działania na wykładnikach.'};
  if(/f\s*\(|podstaw(?:\s|$|ienie|ian|ić|iono|iamy|cie)|wartość funkcji|argument/.test(text))return{code:'SUBSTITUTE',label:'Podstawianie',tip:'Najpierw wpisz argument w każde miejsce zmiennej.',next:'Kolejne podstawienie z kontrolą nawiasów i znaków.'};
  if(/wykres|punkt|oś|osi|nachylen|tabel|współrzęd|diagram/.test(text))return{code:'REPRESENTATION',label:'Odczyt reprezentacji',tip:'Połącz symbol, liczbę i jej miejsce na wykresie, rysunku lub w tabeli.',next:'Nowy odczyt z reprezentacji bez wykonywania zbędnych obliczeń.'};
  if(/figura|kąt|trójkąt|prostokąt|trapez|koło|okrąg|pole figury|obwód|wysokość trójkąta|promień/.test(text))return{code:'GEOMETRY',label:'Rysunek i własności figury',tip:'Zaznacz dane bezpośrednio na figurze i nazwij szukany odcinek lub kąt.',next:'Podobna figura z innymi danymi i tym samym związkiem.'};
  if(/procent|podwyż|obniż|rabat/.test(text))return{code:'PERCENT',label:'Zmiana procentowa',tip:'Ustal, czy liczysz procent liczby, podwyżkę czy obniżkę, i wybierz właściwy mnożnik.',next:'Podobna zmiana procentowa z inną wartością początkową.'};
  if(/prawdopodob|kombin|wyników|średni|median|dominant|danych/.test(text))return{code:'DATA_MODEL',label:'Modelowanie danych',tip:'Oddziel informacje potrzebne od wszystkich danych i nazwij wielkość, którą liczysz.',next:'Nowe dane, ale ten sam sposób wyboru informacji.'};
  if(/wzór|tożsamo|przekształ|równoważ/.test(text))return{code:'FORMULA',label:'Dobór wzoru',tip:'Zapisz potrzebną zależność i dopiero potem podstaw dane.',next:'Zadanie sprawdzające wybór wzoru przed liczeniem.'};
  if(/warunek|dziedzin|możliwe|niemożliwe|istnieje/.test(text))return{code:'CONDITION',label:'Warunki zadania',tip:'Zapisz warunki, które musi spełniać wynik, i sprawdź je na końcu.',next:'Krótki przykład, w którym warunek eliminuje jedną odpowiedź.'};
  if(/oblicz|wyznacz|ile wynosi|wartość/.test(text))return{code:'CALC',label:'Sprawność rachunkowa',tip:'Rozpisz jeden krok w osobnej linii i oszacuj wynik przed wyborem odpowiedzi.',next:'Podobne obliczenie z prostą kontrolą wyniku.'};
  return{code:'READING',label:'Uważne czytanie danych',tip:'Podkreśl, czego szukasz, i odrzuć dane, których nie potrzebujesz.',next:'Krótkie zadanie tekstowe z innymi danymi.'};
}
const ckeMethodProfiles={
  linear:{given:'Wzór, punkty, tabela lub wykres funkcji y = ax + b.',rule:'Nazwij współczynniki a i b, a potem wybierz: odczyt z wykresu, podstawienie albo równanie.'},
  quadratic:{given:'Wzór, wykres, miejsca zerowe albo wierzchołek paraboli.',rule:'Rozpoznaj postać funkcji i wybierz deltę, postać iloczynową albo wierzchołkową.'},
  sequences:{given:'Wyrazy ciągu, wzór ogólny, rekurencja albo warunek.',rule:'Najpierw rozpoznaj rodzaj ciągu; dopiero potem użyj różnicy, ilorazu lub wzoru na sumę.'},
  equations:{given:'Równanie, nierówność, układ albo warunek z parametrem.',rule:'Wykonuj równoważne operacje po obu stronach i na końcu sprawdź warunki.'},
  numbers:{given:'Liczby, potęgi, pierwiastki, logarytmy lub zmiana procentowa.',rule:'Rozpoznaj działanie i zastosuj jedną pasującą własność przed liczeniem.'},
  trigonometry:{given:'Boki, kąty i oznaczenia trójkąta.',rule:'Nazwij boki względem kąta i dobierz sinus, cosinus, tangens albo twierdzenie.'},
  planimetry:{given:'Długości, kąty i własności figury płaskiej.',rule:'Zaznacz dane na rysunku i wybierz jedno twierdzenie lub wzór na pole.'},
  analytic:{given:'Współrzędne punktów, prostej, odcinka albo okręgu.',rule:'Zapisz współrzędne we właściwej kolejności i podstaw je do odpowiedniego wzoru.'},
  expressions:{given:'Wyrażenie algebraiczne i warunki jego określenia.',rule:'Rozpoznaj wspólny czynnik lub wzór, a przy ułamku zacznij od dziedziny.'},
  stereometry:{given:'Wymiary bryły, przekrój albo zaznaczony kąt.',rule:'Nazwij podstawę i wysokość, a potrzebny odcinek znajdź w odpowiednim przekroju.'},
  probability:{given:'Zbiór wyników i opis zdarzenia losowego.',rule:'Policz wszystkie jednakowo możliwe wyniki i osobno wyniki sprzyjające.'},
  dataopt:{given:'Dane z tabeli, wykresu lub warunki zadania optymalizacyjnego.',rule:'Przetłumacz dane na jedną wielkość, wzór lub funkcję celu i pilnuj jej dziedziny.'}
};
function ckeMethodRule(t,step){
  const text=taskText(t,step);
  if(/prostopad/.test(text))return'Porównaj współczynniki kierunkowe: dla prostych prostopadłych a₁ · a₂ = −1.';
  if(/równoleg/.test(text))return'Porównaj współczynniki kierunkowe: proste równoległe mają a₁ = a₂.';
  if(/miejsce zer/.test(text))return'Przyjmij f(x) = 0 i rozwiąż otrzymane równanie.';
  if(/delta|pierwiast.*kwadrat|równani.*kwadrat/.test(text))return'Zapisz a, b, c, oblicz Δ = b² − 4ac i dopiero wybierz wzór na pierwiastki.';
  if(/wierzchoł|wartość największ|wartość najmniejsz|maksimum|minim/.test(text))return'Przejdź do wierzchołka paraboli i sprawdź znak współczynnika a oraz dziedzinę.';
  if(/ciąg.*aryt|różnic.*ciąg|suma.*aryt/.test(text))return'Ustal różnicę r i użyj wzoru aₙ = a₁ + (n−1)r lub właściwego wzoru na sumę.';
  if(/ciąg.*geometr|iloraz.*ciąg|suma.*geometr/.test(text))return'Ustal iloraz q i użyj wzoru aₙ = a₁qⁿ⁻¹ lub właściwego wzoru na sumę.';
  if(/procent|oprocent|lokata/.test(text))return'Zamień procent na mnożnik 1 ± p/100; dla kolejnych zmian mnożniki pomnóż.';
  if(/logarytm/.test(text))return'Przejdź do definicji logₐb = c ⇔ aᶜ = b i sprawdź warunki logarytmu.';
  if(/potęg|pierwiast/.test(text))return'Zapisz liczby ze wspólną podstawą albo wyłącz pełną potęgę spod pierwiastka.';
  if(/prawdopodob|zdarzeni|wyników sprzyj/.test(text))return'Zastosuj P(A) = |A|/|Ω| dopiero po sprawdzeniu jednakowych szans wyników.';
  if(/średni|median|dominant/.test(text))return'Uporządkuj dane i sprawdź, czy zadanie wymaga średniej, mediany czy dominanty.';
  if(/okrąg|promień/.test(text))return'Odczytaj środek i promień z postaci (x−p)² + (y−q)² = r².';
  if(/odległość.*punkt|środek.*odcink/.test(text))return'Podstaw współrzędne parami do wzoru na odległość albo środek odcinka.';
  if(/sin|cos|tang|tg|trygon/.test(text))return'Zaznacz kąt i nazwij bok naprzeciw, bok przy kącie oraz przeciwprostokątną.';
  if(/objęto|pole.*brył|graniastosł|ostrosł|walec|stożek|kula/.test(text))return'Wypisz pole podstawy i wysokość, a następnie zastosuj wzór właściwy dla tej bryły.';
  if(/nierówno/.test(text))return'Wykonuj tę samą operację po obu stronach; po dzieleniu przez liczbę ujemną odwróć znak.';
  if(/równanie|rozwiąż/.test(text))return'Wykonuj równoważne operacje po obu stronach, aż niewiadoma zostanie sama.';
  return(ckeMethodProfiles[t.course||'linear']||ckeMethodProfiles.linear).rule;
}
function ckeMethodCard(t,step){
  const profile=ckeMethodProfiles[t.course||'linear']||{given:`Informacje z działu „${courseById(t.course||'linear').title}”.`,rule:'Nazwij dane, wybierz jedną zależność i sprawdź otrzymany wynik.'},insight=errorInsight(t,step);
  return `<section class="cke-method-card" aria-label="Karta metody CKE"><div class="cke-method-head"><div><span>${icon('target')} KARTA METODY CKE</span><b>Zaplanuj ruch przed zaznaczeniem A–D</b></div><small>Bez ujawniania wyniku</small></div><div class="cke-method-grid"><div class="method-given"><i>1</i><div><span>CO MAM?</span><b>${profile.given}</b></div></div><div class="method-sought"><i>2</i><div><span>CZEGO SZUKAM?</span><b>${escapeHtml(step.q)}</b></div></div><div class="method-rule"><i>3</i><div><span>JAKI RUCH?</span><b>${ckeMethodRule(t,step)}</b></div></div><div class="method-trap"><i>!</i><div><span>NA CO UWAŻAĆ?</span><b>${insight.tip}</b></div></div></div></section>`;
}
function trainingBrief(t){return `<section class="training-brief card"><div class="training-brief-icon">${icon('file')}</div><div><span>${t.origin}</span><h2>${t.problem}</h2></div><b>${t.points}</b></section>`;}
function trainingMethodDisclosure(t,step){return `<details class="training-method-disclosure card"><summary><span class="method-summary-icon">${icon('target')}</span><span class="method-summary-copy"><b>Plan rozwiązania CKE</b><small>Najpierw zaplanuj ruch, potem zaznacz odpowiedź A–D.</small></span><span class="method-summary-action"><em class="when-closed">Pokaż 4 kroki</em><em class="when-open">Ukryj kroki</em><span class="method-summary-chevron" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m7 9 5 5 5-5"/></svg></span></span></summary>${ckeMethodCard(t,step)}</details>`;}
function workedSolution(step){
  const conclusion=String(step.conclusion||'').trim(),hints=[...new Set((step.hints||[]).map(hint=>String(hint||'').trim()).filter(hint=>hint&&hint!==conclusion))],labels=['Rozpoznaj','Zastosuj','Sprawdź'];
  return `<div class="worked-solution">${window.E8SolutionPlayer?.render(step)||''}<span>ROZWIĄZANIE KROK PO KROKU</span><ol>${hints.map((hint,index)=>`<li><i>${index+1}</i><div><b>${labels[index]||`Krok ${index+1}`}</b><p>${hint}</p></div></li>`).join('')}<li class="solution-result"><i>✓</i><div><b>Wniosek</b><p>${conclusion}</p></div></li></ol></div>`;
}
function recordErrorProfile(label,taskId,insight=null){const detail=insight||{label},current=saved.errorProfile[label]||{count:0,taskIds:[],history:[]};current.count=(current.count||0)+1;current.last=new Date().toISOString();current.code=detail.code||current.code||'OTHER';current.tip=detail.tip||current.tip||'';current.next=detail.next||current.next||'';current.taskIds=[taskId,...(current.taskIds||[]).filter(id=>id!==taskId)].slice(0,8);current.history=[{taskId,at:current.last},...(current.history||[])].slice(0,12);saved.errorProfile[label]=current;persist();}
function registerError(t,step){if(state.errorSteps.includes(state.step))return errorInsight(t,step);const insight=errorInsight(t,step);state.errorSteps.push(state.step);state.errorTypes.push(insight.label);recordErrorProfile(insight.label,state.task,insight);return insight;}
function dominantErrorType(){if(!state.errorTypes.length)return null;const counts=state.errorTypes.reduce((all,label)=>(all[label]=(all[label]||0)+1,all),{});return Object.entries(counts).sort((a,b)=>b[1]-a[1])[0][0];}
function feedbackPlain(value){return String(value||'').replace(/<[^>]*>/g,' ').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();}
function legacyChoiceExplanation(step,picked,showSolution=true){
  const chosen=feedbackPlain(step.options?.[picked]),right=feedbackPlain(step.options?.[step.correct]);
  const hints=[...new Set([...(step.hints||[]),step.hint].filter(Boolean).map(feedbackPlain))];
  const proof=feedbackPlain(step.conclusion||step.why||hints.at(-1));
  const clean=value=>value.replace(/[−–]/g,'-').replace(/,/g,'.').replace(/^\w+\s*=\s*/,'').trim();
  const numeric=value=>{const v=clean(value),m=v.match(/^(-?\d+(?:\.\d+)?)(?:\/(-?\d+(?:\.\d+)?))?$/);return m?Number(m[1])/(m[2]?Number(m[2]):1):null;};
  const a=numeric(chosen),b=numeric(right);let contrast='';
  if(a!==null&&b!==null&&a!==b){
    if(a===-b)contrast='Ten wynik ma przeciwny znak. ';
    else if(a!==0&&b!==0&&Math.abs(a*b-1)<1e-9)contrast='Ten wynik jest odwrotnością właściwej wartości. ';
    else if(b!==0&&a===2*b)contrast='Ten wynik jest dwukrotnie większy od właściwej wartości. ';
    else if(b!==0&&2*a===b)contrast='Ten wynik jest połową właściwej wartości. ';
  }
  const point=value=>value.replace(/\s/g,'').match(/^\(([^,]+),([^,]+)\)$/),pa=point(chosen),pb=point(right);
  if(pa&&pb&&pa[1]===pb[2]&&pa[2]===pb[1])contrast='Współrzędne są zamienione miejscami: zapis punktu to (x, y). ';
  if(/^(x|k|m|p)\s*[<>≤≥]/.test(chosen)&&/^(x|k|m|p)\s*[<>≤≥]/.test(right)){
    const signs=value=>value.match(/[<>≤≥]/)?.[0],boundary=value=>clean(value.replace(/^[^<>≤≥]*[<>≤≥]/,''));
    if(boundary(chosen)===boundary(right)&&signs(chosen)!==signs(right))contrast='Granica jest właściwa, ale znak nierówności opisuje inny zbiór liczb. ';
  }
  if(!showSolution)return `Wybrana odpowiedź: „${chosen}”. ${contrast}${hints[0]||'Porównaj tę odpowiedź z danymi zadania.'}`;
  const reasoning=[...new Set([...hints,proof].filter(Boolean))].join(' ');
  return `Wybrana odpowiedź: „${chosen}”. ${contrast}${reasoning} Dlatego poprawna odpowiedź to „${right}”.`;
}
function wrongChoiceFeedback(step,picked,showSolution=true){
  if(!Number.isInteger(picked)||!step.options?.[picked])return escapeHtml(feedbackPlain(step.hints?.[0]||step.hint||step.conclusion||step.why));
  return escapeHtml(step.optionFeedback?.[picked]||legacyChoiceExplanation(step,picked,showSolution));
}


function questionCard(step,total){const nextLabel=state.reviewReturn?(state.currentDeferred?'Wróć do Powtórek':'Zapisz i wróć do Powtórek'):state.step===total-1?'Zakończ serię':'Następny przykład',competency=ckeCompetency(tasks[state.task],step);return `<div class="question-card embedded"><div class="question-topline"><div class="question-context-row"><div class="question-kicker">${icon('brain')} Teraz: przykład ${state.step+1} z ${total}</div><span class="cke-skill-chip">CKE ${competency.code} · ${competency.label}</span></div><button class="sound-toggle" id="soundToggle" aria-pressed="${saved.soundEnabled}" title="Włącz lub wyłącz dźwięki odpowiedzi"><span aria-hidden="true">${saved.soundEnabled?'🔊':'🔇'}</span>${saved.soundEnabled?'Dźwięk włączony':'Dźwięk wyłączony'}</button></div><h3>${step.q}</h3><div class="answers">${shuffledOptions(step).map((optionIndex,displayIndex)=>`<button class="answer choice-answer ${state.selected&&optionIndex===state.currentPicked&&!state.currentDeferred?'correct':(state.wrongChoices||[]).includes(optionIndex)?'wrong':''}" data-answer="${optionIndex}" ${state.selected||(state.wrongChoices||[]).includes(optionIndex)?'disabled':''}><i class="answer-letter">${'ABCD'[displayIndex]}</i><span>${step.options[optionIndex]}</span></button>`).join('')}</div><div class="feedback ${state.selected?(state.currentDeferred?'deferred-feedback':'correct explanation-feedback'):state.stepMistakes?'wrong':''}" role="status" aria-live="polite">${state.feedback||restoredLessonFeedback(step)}</div><div class="question-actions"><button class="hint-btn" id="hintButton" ${state.selected?'disabled':''}>${icon('light')} Podpowiedź ${state.hint?state.hint+1:''}</button><button class="primary-btn next-btn ${state.selected?'ready':''}" id="nextStep" ${state.selected?'':'disabled'}>${nextLabel} ${icon('arrow')}</button></div></div>`;}
function taskPath(t){
  const courseId=t.course||'linear';
  if(courseId==='linear')return pathways.find(item=>item.id===t.path)||activePath();
  if(courseId==='quadratic')return quadraticPathways.find(item=>item.id===t.path)||activeQuadraticPath();
  if(courseId==='sequences')return sequencePathways.find(item=>item.id===t.path)||activeSequencePath();
  if(courseId==='equations')return algebraPathways.find(item=>item.id===t.path)||activeAlgebraPath();
  return extraSubjectSpecs[courseId]?.paths.find(item=>item.id===t.path)||null;
}
function courseTrainingComplete(courseId){const ids=courseById(courseId).taskIds.filter(id=>!tasks[id]?.exam);return ids.length>0&&ids.every(taskIsMastered);}
function successCard(t){
  const courseId=t.course||'linear',path=taskPath(t),pathTasks=(path?.taskIds||[]).filter(id=>!tasks[id]?.exam),next=pathTasks[pathTasks.indexOf(state.task)+1]||null,readyForExam=courseTrainingComplete(courseId),score=guidedScore(),total=lessonSteps(t).length,deferred=state.skippedSteps.length,correct=total-deferred,status=deferred?'DO POWTÓRKI':score>=80?'OPANOWANE':'W TRAKCIE',statusClass=deferred?'review':score>=80?'mastered':'progress',backRoute=courseId==='linear'?'path':courseId==='quadratic'?'qpath':courseId==='sequences'?'spath':courseId==='equations'?'apath':'course',backTarget=courseId==='linear'?path?.id:courseId==='quadratic'||courseId==='sequences'||courseId==='equations'?path?.id:courseId,conclusion=lessonSteps(t).at(-1)?.conclusion||`Utrwaliłeś temat: ${t.topic}.`,errorType=dominantErrorType(),targeted=errorType?taskForErrorType(errorType,[state.task]):null,planTask=Boolean(saved.diagnostic&&saved.studyPlan?.taskIds?.includes(state.task)),repeatText=deferred?`${deferred} ${deferred===1?'przykład czeka':'przykłady czekają'} w Powtórkach`:state.mistakes?'Wróć do pytań, przy których była pomyłka':'Brak pilnej powtórki';
  const nextText=deferred?'Najpierw popraw odłożone pytania.':planTask?'Wróć do mapy umiejętności i sprawdź następny krok planu.':targeted?`Wykryliśmy schemat „${errorType}”. Następna seria będzie dobrana dokładnie pod niego.`:next?'Kolejna seria utrwali następny schemat.':readyForExam?'Trening kursu ukończony — czas sprawdzić się samodzielnie.':'Ten dział jest zakończony — wybierz kolejny.';
  const nextButton=deferred?`<button class="primary-btn" data-route="review">Zobacz odłożone ${icon('arrow')}</button>`:planTask?`<button class="primary-btn" data-route="diagnostic">Wróć do planu ${icon('arrow')}</button>`:targeted?`<button class="primary-btn" data-route="learn" data-task="${targeted}">Trening celowany ${icon('arrow')}</button>`:next?`<button class="primary-btn" data-route="learn" data-task="${next}">Następna seria ${icon('arrow')}</button>`:readyForExam?`<button class="primary-btn" data-route="exam" data-target="${courseId}">Przejdź do sprawdzianu CKE ${icon('arrow')}</button>`:`<button class="primary-btn" data-route="${backRoute}" data-target="${backTarget}">Wybierz kolejny dział ${icon('arrow')}</button>`;
  return `<article class="success-card summary-card card ${deferred?'with-deferred':''}"><div class="success-heading"><div class="success-icon">${deferred?icon('refresh'):icon('check')}</div><div><span class="series-status state-${statusClass}">${status} · ${score}%</span><h2>${total===1?'Przykład zakończony':`Seria ${total} przykładów zakończona`}</h2><p>${deferred?'Trudne pytania są bezpiecznie zapisane i wrócą w Powtórkach.':`Masz zapisany wynik. ${reviewIntervalLabel(state.task)}.`}</p></div></div><div class="series-diagnosis-grid"><div class="diagnosis-mastered"><span>UMIEM</span><strong>${correct}/${total}</strong><small>${t.topic}</small></div><div class="diagnosis-repeat"><span>POWTÓRZYĆ</span><strong>${deferred||state.mistakes}</strong><small>${repeatText}</small></div><div class="diagnosis-error"><span>TYP BŁĘDU</span><strong>${errorType||'Brak'}</strong><small>${errorType?'To ten schemat pojawiał się najczęściej.':'Nie wykryliśmy powtarzającej się pułapki.'}</small></div></div><section class="series-takeaway"><span>NAJWAŻNIEJSZY WNIOSEK</span><p>${conclusion}</p></section><section class="series-next"><div><span>CO DALEJ?</span><b>${nextText}</b></div><div class="success-actions"><button class="secondary-btn" id="restartTask">Powtórz serię</button>${window.E8_OPEN_WORK?.[courseId]?`<button class="secondary-btn" data-route="openwork" data-target="${courseId}">Zadania krok po kroku ${icon('arrow')}</button>`:''}${nextButton}</div></section></article>`;
}

