function advanceLessonStep(steps,step,correct){state.answers.push(correct?step.options[step.correct]:null);state.step++;state.selected=false;state.currentDeferred=false;state.hint=0;state.stepMistakes=0;state.feedback='';state.feedbackType='';state.optionOrder=null;state.wrongChoices=[];state.hintShown=false;state.currentPicked=null;if(state.step===steps.length){const complete=state.skippedSteps.length===0;recordOutcome(state.task,'guided',complete,state.hintUsed);logStudySession('series',state.task,tasks[state.task]?.title||'Seria kursu');playFeedbackTone('achievement');showToast(complete?'Seria ukończona bez odłożonych pytań.':'Seria zakończona. Odłożone pytania czekają w Powtórkach.');}else playFeedbackTone('progress');saveTaskProgress();render();setTimeout(()=>$('.focus-task,.success-card')?.scrollIntoView({behavior:'smooth',block:'center'}),50);}

function bindDailySession(){
  $$('[data-daily-answer]').forEach(button=>button.addEventListener('click',()=>{
    const session=ensureDailySession(),index=Number(session.current)||0;
    if(session.answers[index])return;
    const entry=session.pack[index],task=tasks[entry.taskId],step=lessonSteps(task)[entry.stepIndex],picked=Number(button.dataset.dailyAnswer),attempt=session.attempt&&session.attempt.index===index?session.attempt:{index,mistakes:0,wrongChoices:[]};
    if(picked===step.correct){
      const insight=errorInsight(task,step),errorType=attempt.mistakes?insight.label:null,adapted=adaptNextDailyQuestion(session,index,{correct:true,mistakes:attempt.mistakes});
      session.answers[index]={taskId:entry.taskId,stepIndex:entry.stepIndex,kind:entry.kind,picked,correct:true,mistakes:attempt.mistakes,wrongChoices:[...attempt.wrongChoices],answeredAt:new Date().toISOString(),errorType,errorCode:errorType?insight.code:null,confidence:attempt.mistakes?'corrected':'first_try'};
      session.attempt=null;
      saved.wrong=saved.wrong.filter(item=>!(item.id===entry.taskId&&item.step===entry.stepIndex));
      saveImprovement(task,step,attempt.mistakes>0);
      recordPracticeOutcome(entry.taskId,entry.stepIndex,true,false);
      if(errorType)recordErrorProfile(errorType,entry.taskId,insight);
      persist();
      trackPilotEvent('daily_answered',{sessionDate:session.date,questionIndex:index,taskId:entry.taskId,taskTitle:task.title,topic:task.topic,kind:entry.kind,correct:true,mistakes:attempt.mistakes,errorType,errorCode:errorType?insight.code:null,nextKind:adapted?.kind||null},`answer-${session.date}-${index}`);
      playFeedbackTone('correct');renderWithoutScrollJump();return;
    }
    attempt.mistakes+=1;attempt.wrongChoices=[...new Set([...attempt.wrongChoices,picked])];session.attempt=attempt;playFeedbackTone('wrong');
    if(attempt.mistakes<2){persist();renderWithoutScrollJump();return;}
    const insight=errorInsight(task,step),item={id:entry.taskId,task:task.title,question:step.q,step:entry.stepIndex,source:'daily',reason:'Dwie nieudane próby w sesji dobranej do Twojego profilu.'},adapted=adaptNextDailyQuestion(session,index,{correct:false,mistakes:2});
    session.answers[index]={taskId:entry.taskId,stepIndex:entry.stepIndex,kind:entry.kind,picked,correct:false,mistakes:2,wrongChoices:[...attempt.wrongChoices],answeredAt:new Date().toISOString(),errorType:insight.label,errorCode:insight.code,confidence:'failed'};
    session.attempt=attempt;
    rememberWrong(item,insight);
    recordPracticeOutcome(entry.taskId,entry.stepIndex,false,false);recordErrorProfile(insight.label,entry.taskId,insight);persist();
    trackPilotEvent('daily_answered',{sessionDate:session.date,questionIndex:index,taskId:entry.taskId,taskTitle:task.title,topic:task.topic,kind:entry.kind,correct:false,mistakes:2,errorType:insight.label,errorCode:insight.code,nextKind:adapted?.kind||null},`answer-${session.date}-${index}`);
    renderWithoutScrollJump();
  }));
  $('[data-report-open]')?.addEventListener('click',()=>{state.dailyReportOpen=!state.dailyReportOpen;render();});
  $$('[data-report-category]').forEach(button=>button.addEventListener('click',()=>{const session=ensureDailySession(),index=Number(session.current)||0,entry=session.pack[index],task=tasks[entry.taskId];session.reports=Array.isArray(session.reports)?session.reports:[];if(!session.reports.some(report=>report.questionIndex===index)){session.reports.push({questionIndex:index,taskId:entry.taskId,stepIndex:entry.stepIndex,category:button.dataset.reportCategory,createdAt:new Date().toISOString()});trackPilotEvent('daily_issue_report',{sessionDate:session.date,questionIndex:index,taskId:entry.taskId,taskTitle:task?.title||entry.taskTitle,topic:task?.topic||entry.topic,stepIndex:entry.stepIndex,category:button.dataset.reportCategory},`report-${session.date}-${index}`);}state.dailyReportOpen=false;persist();render();}));
  $$('[data-session-rating]').forEach(button=>button.addEventListener('click',()=>{const session=ensureDailySession();if(session.difficulty)return;session.difficulty=button.dataset.sessionRating;session.difficultyRatedAt=new Date().toISOString();persist();trackPilotEvent('daily_session_difficulty',{sessionDate:session.date,courseId:session.courseId,difficulty:session.difficulty,correct:(session.answers||[]).filter(answer=>answer?.correct).length},`difficulty-${session.date}`);render();}));
  $('#dailyNext')?.addEventListener('click',()=>{const session=ensureDailySession(),index=Number(session.current)||0;if(!session.answers[index])return;session.current=index+1;session.attempt=null;state.dailyReportOpen=false;if(session.current>=session.pack.length){session.completedAt=new Date().toISOString();const correct=session.answers.filter(answer=>answer?.correct).length,durationSeconds=Math.max(0,Math.round((new Date(session.completedAt).getTime()-new Date(session.telemetryStartedAt||session.createdAt).getTime())/1000));trackPilotEvent('daily_session_completed',{sessionDate:session.date,courseId:session.courseId,correct,incorrect:session.answers.length-correct,durationSeconds},`complete-${session.date}`);playFeedbackTone('achievement');}else playFeedbackTone('progress');persist();render();window.scrollTo({top:0,behavior:'smooth'});});
}

function bindLesson(){const t=tasks[state.task],steps=lessonSteps(t),step=steps[state.step];
  $('#soundToggle')?.addEventListener('click',()=>{saved.soundEnabled=!saved.soundEnabled;persist();const toggle=$('#soundToggle');toggle.setAttribute('aria-pressed',saved.soundEnabled);toggle.innerHTML=`<span aria-hidden="true">${saved.soundEnabled?'🔊':'🔇'}</span>${saved.soundEnabled?'Dźwięk włączony':'Dźwięk wyłączony'}`;if(saved.soundEnabled)playFeedbackTone('correct');});
  $$('[data-answer]').forEach(btn=>btn.addEventListener('click',()=>requestAnimationFrame(()=>{if(t.visual!=='algebra'||!state.selected)return;const root=$('#visualRoot'),note=$('#visualNote');if(root)root.innerHTML=taskVisual(t);if(note)note.textContent=visualNote(t);})));
  $$('[data-answer]').forEach(btn=>btn.addEventListener('click',()=>{if(state.selected)return;const picked=Number(btn.dataset.answer),card=$('.question-card'),feedback=$('.feedback');state.currentPicked=picked;state.feedback='';state.hintShown=false;if(picked===step.correct){btn.classList.add('correct');card.classList.remove('answer-error');card.classList.add('answer-success');$('.visual-panel')?.classList.add('celebrate');playFeedbackTone('correct');state.selected=true;state.currentDeferred=false;state.feedbackType='correct';saved.wrong=saved.wrong.filter(item=>!(item.id===state.task&&item.step===state.step));persist();$$('[data-answer]').forEach(x=>x.disabled=true);const next=$('#nextStep');next.disabled=false;next.classList.add('ready');$('#hintButton').disabled=true;feedback.innerHTML=`<div class="feedback-title">${icon('check')}<div><b>Poprawnie: ${step.options[step.correct]}</b><span>Teraz zobacz pełny tok, nie tylko wynik.</span></div></div>${workedSolution(step)}<small>Wyjaśnienie zostaje na ekranie. Kliknij dalej dopiero, kiedy wszystko jest jasne.</small>`;feedback.className='feedback correct explanation-feedback';}else{state.mistakes++;state.stepMistakes++;state.wrongChoices=[...new Set([...(state.wrongChoices||[]),picked])];const insight=registerError(t,step);btn.classList.add('wrong');btn.disabled=true;card.classList.remove('answer-error');requestAnimationFrame(()=>card.classList.add('answer-error'));playFeedbackTone('wrong');if(state.stepMistakes===1){feedback.innerHTML=`<div class="feedback-title error-title"><i class="feedback-alert" aria-hidden="true">!</i><div><b>To pierwsza z dwóch prób.</b><span class="error-pattern">Pułapka: ${insight.label}</span></div></div><span>${wrongChoiceFeedback(step,picked,false)}</span><small>${insight.tip} Spróbuj ponownie — poprawnej odpowiedzi jeszcze nie pokazujemy.</small>`;feedback.className='feedback wrong';saveTaskProgress();setTimeout(()=>card.classList.remove('answer-error'),500);return;}const answerLetter='ABCD'[state.optionOrder.indexOf(step.correct)],item={id:state.task,task:t.title,question:step.q,step:state.step,source:'course',reason:'Dwie nieudane próby w tej samej serii kursu.'};rememberWrong(item,insight);if(!state.skippedSteps.includes(state.step))state.skippedSteps.push(state.step);persist();state.selected=true;state.currentDeferred=true;$$('[data-answer]').forEach(x=>x.disabled=true);$('#hintButton').disabled=true;const next=$('#nextStep');next.disabled=false;next.classList.add('ready');if(state.reviewReturn)next.innerHTML=`Wróć do Powtórek ${icon('arrow')}`;feedback.innerHTML=`<div class="feedback-title deferred-title">${icon('refresh')}<div><b>Odkładamy pytanie do Powtórek</b><span>Poprawna była <strong>${answerLetter}: ${step.options[step.correct]}</strong></span></div></div><span class="error-pattern">Pułapka: ${insight.label} · ${insight.tip}</span><p class="choice-explanation">${wrongChoiceFeedback(step,picked)}</p>${workedSolution(step)}<small>Rozwiązanie nie zniknie. To Ty decydujesz, kiedy kliknąć „${state.reviewReturn?'Wróć do Powtórek':'Następny przykład'}”.</small>`;feedback.className='feedback deferred-feedback';}saveTaskProgress();}));
  $$('[data-answer]').forEach(btn=>btn.addEventListener('click',()=>requestAnimationFrame(()=>{if(Number(btn.dataset.answer)!==step.correct||!state.selected)return;const improvement=saveImprovement(t,step,state.stepMistakes>0);const solution=$('.worked-solution');if(solution&&!$('.feedback-progress-win'))solution.insertAdjacentHTML('beforebegin',improvementMarkup(improvement));})));
  $('#hintButton')?.addEventListener('click',()=>{playFeedbackTone('hint');const hints=step.hints;state.hintUsed=true;state.hintShown=true;state.hint=Math.min(state.hint,hints.length-1);state.lastHint=state.hint;state.feedback=`Podpowiedź: ${hints[state.hint]}`;state.feedbackType='';$('.feedback').innerHTML=`<b>Podpowiedź</b><span>${hints[state.hint]}</span>`;$('.feedback').className='feedback';state.hint=Math.min(state.hint+1,hints.length-1);saveTaskProgress();});
  $('#nextStep')?.addEventListener('click',()=>{if(!state.selected)return;if(state.reviewReturn){if(!state.currentDeferred){recordPracticeOutcome(state.task,state.step,true,state.hintUsed);showToast('Pytanie poprawione i usunięte z kolejki.');}discardTaskProgress();state.reviewReturn=false;state.currentDeferred=false;routeTo('review');return;}advanceLessonStep(steps,step,!state.currentDeferred);});
  $('#restartTask')?.addEventListener('click',()=>{discardTaskProgress();resetTask();render();});
  $('#mSlider')?.addEventListener('input',e=>{const m=Number(e.target.value);$('#mValue').textContent=Number.isInteger(m)?m:m.toFixed(1);$('#visualRoot').innerHTML=linearGraph(m);$('#visualNote').textContent=Math.abs(m-3)<.05?'Teraz a = 0. Wykres to pozioma prosta y = −4 — nie ma miejsca zerowego.':`Teraz a = ${(3-m).toFixed(1)}. Prosta przecina oś x, więc miejsce zerowe istnieje.`;});
}
function bindExam(){
  $$('[data-exam-set]').forEach(button=>button.addEventListener('click',()=>{state.examVariant=Number(button.dataset.examSet);resetExamSession();state.examVariant=Number(button.dataset.examSet);render();}));
  $('#startExam')?.addEventListener('click',()=>{state.examStartedAt=Date.now();state.examAnswers={};state.examRubricScores={};state.examFlagged={};state.examStages={};state.examCurrent=0;state.examReview=false;state.examSelfCheck=false;state.examSubmitted=false;state.examResult=null;saveExamProgress();render();});
  $('#examOpenDraft')?.addEventListener('input',event=>{const id=activeExamSet().taskIds[state.examCurrent];setExamOpenDraft(id,event.target.value);saveExamProgress();});
  $$('[data-exam-choice]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.examChoice;setExamAnswer(id,examStageIndex(id),Number(button.dataset.choice));playFeedbackTone('select');saveExamProgress();renderWithoutScrollJump();}));
  $$('[data-exam-stage]').forEach(button=>button.addEventListener('click',()=>{const id=activeExamSet().taskIds[state.examCurrent];state.examStages[id]=Number(button.dataset.examStage);saveExamProgress();render();}));
  $('#examStagePrev')?.addEventListener('click',()=>{const id=activeExamSet().taskIds[state.examCurrent];state.examStages[id]=Math.max(0,examStageIndex(id)-1);saveExamProgress();render();});
  $('#examStageNext')?.addEventListener('click',()=>{const id=activeExamSet().taskIds[state.examCurrent],stage=examStageIndex(id);if(!Number.isInteger(examAnswerFor(id,stage)))return;state.examStages[id]=Math.min(examStepsForTask(tasks[id]).length-1,stage+1);saveExamProgress();render();});
  $$('[data-exam-nav]').forEach(button=>button.addEventListener('click',()=>{state.examCurrent=Number(button.dataset.examNav);saveExamProgress();render();}));
  $('#examFlag')?.addEventListener('click',()=>{const id=activeExamSet().taskIds[state.examCurrent];state.examFlagged[id]=!state.examFlagged[id];saveExamProgress();render();});
  $('#examPrev')?.addEventListener('click',()=>{state.examCurrent=Math.max(0,state.examCurrent-1);saveExamProgress();render();});
  $('#examNext')?.addEventListener('click',()=>{state.examCurrent=Math.min(activeExamSet().taskIds.length-1,state.examCurrent+1);saveExamProgress();render();});
  $('#openExamReview')?.addEventListener('click',()=>{playFeedbackTone('submit');state.examReview=true;saveExamProgress();render();window.scrollTo({top:0,behavior:'smooth'});});
  $('#backToExam')?.addEventListener('click',()=>{state.examReview=false;saveExamProgress();render();window.scrollTo({top:0,behavior:'smooth'});});
  $$('[data-review-nav]').forEach(button=>button.addEventListener('click',()=>{state.examCurrent=Number(button.dataset.reviewNav);state.examReview=false;saveExamProgress();render();window.scrollTo({top:0,behavior:'smooth'});}));
  $$('[data-result-nav]').forEach(button=>button.addEventListener('click',()=>{state.examCurrent=Number(button.dataset.resultNav);render();setTimeout(()=>$('.exam-focus-question')?.scrollIntoView({behavior:'smooth',block:'start'}),50);}));
  $$('[data-selfcheck-nav]').forEach(button=>button.addEventListener('click',()=>{const openIds=activeExamSet().taskIds.filter(id=>tasks[id]?.fullExamOpen),next=openIds[Number(button.dataset.selfcheckNav)];if(!next)return;state.examCurrent=activeExamSet().taskIds.indexOf(next);saveExamProgress();render();window.scrollTo({top:0,behavior:'smooth'});}));
  $$('[data-exam-rubric]').forEach(button=>button.addEventListener('click',()=>{const id=activeExamSet().taskIds[state.examCurrent];state.examRubricScores[id]=Number(button.dataset.examRubric);playFeedbackTone('select');saveExamProgress();renderWithoutScrollJump();}));
  $('#finalizeExamScore')?.addEventListener('click',()=>finishExam(true));
  $$('[data-submit-exam]').forEach(button=>button.addEventListener('click',()=>{const ids=activeExamSet().taskIds,missing=ids.filter(id=>!hasExamAnswer(id)).length;if(missing&&!window.confirm(`Brakuje odpowiedzi w ${missing} ${missing===1?'zadaniu':'zadaniach'}. Oddać arkusz mimo to?`))return;if(fullExamMode()&&ids.some(id=>tasks[id]?.fullExamOpen)){beginExamSelfAssessment();return;}finishExam(true);}));
  $('#restartExam')?.addEventListener('click',()=>{const variant=state.examVariant;resetExamSession();state.examVariant=variant;render();});
  $('#chooseExam')?.addEventListener('click',()=>{resetExamSession();render();});
  clearInterval(state.examTimer);state.examTimer=null;
  if(state.examStartedAt&&!state.examSubmitted&&!state.examSelfCheck){const updateClock=()=>{const left=examTimeLeft(),clock=$('#examClock');if(clock)clock.textContent=formatTime(left);if(left<=0){if(fullExamMode()&&activeExamSet().taskIds.some(id=>tasks[id]?.fullExamOpen))beginExamSelfAssessment();else finishExam(true);}};updateClock();if(!state.examSubmitted&&!state.examSelfCheck)state.examTimer=setInterval(updateClock,1000);}
}

function correctE8Copy(root){
  root.querySelector('.guide-route-map')?.remove();
  root.querySelector('.diagnostic-note')?.remove();
  root.querySelectorAll('.daily-preview-copy h2,.session-page-head h1').forEach(sessionTitle=>sessionTitle.textContent=sessionTitle.textContent.replace(' dobrane dla Ciebie',' dobranych dla Ciebie'));
  const welcomeDiagnostic=root.querySelector('.welcome-plan ol li:first-child small');
  if(welcomeDiagnostic)welcomeDiagnostic.textContent='24–40 pytań dopasowanych do wybranego celu';
  const welcomeIntro=root.querySelector('.welcome-copy>p');
  if(welcomeIntro)welcomeIntro.textContent='Ustaw cel, poznaj sposób działania panelu i rozwiąż dokładną diagnozę. Potem dostaniesz kolejność nauki dopasowaną do swoich odpowiedzi.';
  const knowledgeEyebrow=root.querySelector('.kb-head .eyebrow');
  if(knowledgeEyebrow&&knowledgeEyebrow.textContent.includes('Kompendium'))knowledgeEyebrow.innerHTML=`${icon('book')} Podręcznik E8`;
  const welcomeButton=root.querySelector('#finishWelcome');
  if(welcomeButton&&!welcomeButton.dataset.guideBound){welcomeButton.dataset.guideBound='true';welcomeButton.innerHTML=`Zobacz, jak korzystać ${icon('arrow')}`;welcomeButton.addEventListener('click',()=>setTimeout(()=>routeTo('guide'),0),{once:true});}
  const milestone=root.querySelector('.milestone-card h2'),milestoneCount=Number.parseInt(milestone?.textContent||'',10);
  if(milestone&&Number.isFinite(milestoneCount)){const mod10=milestoneCount%10,mod100=milestoneCount%100,word=milestoneCount===1?'element':mod10>=2&&mod10<=4&&!(mod100>=12&&mod100<=14)?'elementy':'elementów';milestone.textContent=`${milestoneCount} ${word} do celu`;}
  const progressNote=root.querySelector('.progress-local-note');
  if(progressNote)progressNote.textContent=window.smartMaturaCloud?.configured?.()?'Postęp zapisuje się automatycznie na koncie.':'Postęp zapisuje się automatycznie w tej przeglądarce.';
  const sessionForecast=root.querySelector('.session-complete-stats>div:nth-child(3) b'),forecast=scoreForecast();
  if(sessionForecast&&forecast.hasData)sessionForecast.textContent=forecast.range;
}

const renderBase=render;
render=function(){
  if(state.route==='guide'){
    const shell=$('.app-shell');shell?.classList.remove('focus-mode');$('#sidebar')?.classList.remove('open');
    $('#appMain').innerHTML=courseGuidePage();
    $$('.nav-item').forEach(item=>item.classList.toggle('active',item.dataset.route==='guide'));
    const name=saved.studentName.trim()||'Uczeń',profileName=$('.profile-copy strong'),avatar=$('.avatar');
    if(profileName)profileName.textContent=name;if(avatar)avatar.textContent=name.split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();
    bindDynamic();
  }else renderBase();
  correctE8Copy($('#appMain'));formatMathIn($('#appMain'));
};


window.smartE8ReportContext=function(){
  let task=null,step=null,index=null,id=null,picked=null;
  if(state.route==='learn'){id=state.task;task=tasks[id];index=state.step;step=task&&lessonSteps(task)[index];picked=state.currentPicked;}
  else if(state.route==='session'){const data=dailySessionStatus();task=data.task;step=data.currentStep;id=data.currentEntry?.taskId;index=data.currentEntry?.stepIndex;picked=data.session.answers[data.currentIndex]?.picked??data.session.attempt?.wrongChoices?.at(-1)??null;}
  else if(state.route==='exam'){id=activeExamSet().taskIds[state.examCurrent];task=tasks[id];index=task?examStageIndex(id):0;step=task&&examStepsForTask(task)[index];picked=id?examAnswerFor(id,index):null;}
  else if(state.route==='openwork'){task=openWorkVariants(state.activeCourse)[state.openWorkVariant];index=openWorkProgress(state.activeCourse,state.openWorkVariant).step;const row=task?.steps[index];step=row?{q:row[0],options:row[1],correct:row[2]}:null;id=`openwork:${state.activeCourse}:${state.openWorkVariant}`;picked=openWorkUi.wrong.at(-1)??null;}
  else if(state.route==='selfwork'){const progress=selfWorkProgress(state.activeCourse),entries=selfWorkTasks(state.activeCourse);index=progress.cursor;task=entries[index];step=task?{q:task.problem,options:[],correct:null}:null;id=`selfwork:${state.activeCourse}:${index+1}`;picked=progress.drafts[index]||null;}

  else if(state.route==='diagnostic'&&diagnosticState.started){const item=diagnosticQuestions[diagnosticState.current];if(item){task={title:item.q,course:item.course};step=item;id=item.id;index=diagnosticState.current;picked=diagnosticState.answers[item.id]??null;}}
  return {route:state.route,knowledgeCourse:state.route==='knowledge'?knowledgeState.course:null,knowledgeTopic:state.route==='knowledge'?knowledgeState.topic:null,course:task?.course||state.activeCourse,taskId:id||'',taskTitle:feedbackPlain(task?.title),problem:feedbackPlain(task?.problem),question:feedbackPlain(step?.q),stepIndex:index,options:step?.options?.map(feedbackPlain)||[],picked};
};
