window.addEventListener('hashchange',()=>{const [r,target]=location.hash.slice(1).split('/');if(!r)return;state.route=r;if(r==='knowledge'){knowledgeState.course=target&&knowledgeBase[target]?target:null;knowledgeState.topic=null;}else if(r==='course'&&target)state.activeCourse=target;else if(r==='openwork'&&window.E8_OPEN_WORK?.[target?.split('|')[0]]){const [courseId,variant]=target.split('|');state.activeCourse=courseId;state.openWorkVariant=requestedOpenWorkVariant(courseId,variant);openWorkUi.wrong=[];openWorkUi.message='';}else if(r==='selfwork'&&window.E8_SELF_WORK?.[target]){state.activeCourse=target;selfWorkUi.hintOpen=false;}else if(r==='xpath'&&target)setExtraPathContext(target);else if(r==='path'&&target){state.activeCourse='linear';state.activePath=target;}else if(r==='qpath'&&target){state.activeCourse='quadratic';state.activeQuadraticPath=target;}else if(r==='spath'&&target){state.activeCourse='sequences';state.activeSequencePath=target;}else if(r==='apath'&&target){state.activeCourse='equations';state.activeAlgebraPath=target;}else if(r==='exam'&&target){state.examCourse=target;}else if(r==='review')restoreReviewCourse();else if(target&&tasks[target]&&target!==state.task){state.task=target;state.activeCourse=tasks[target].course||'linear';if(state.activeCourse==='quadratic')state.activeQuadraticPath=tasks[target].path||state.activeQuadraticPath;else if(state.activeCourse==='sequences')state.activeSequencePath=tasks[target].path||state.activeSequencePath;else if(state.activeCourse==='equations')state.activeAlgebraPath=tasks[target].path||state.activeAlgebraPath;else if(extraSubjectSpecs[state.activeCourse])state.activeExtraPath=tasks[target].path||state.activeExtraPath;else state.activePath=tasks[target].path||state.activePath;resetTask();}render();});
const initial=location.hash.slice(1).split('/');if(initial[0]){state.route=initial[0];if(initial[0]==='knowledge'){knowledgeState.course=initial[1]&&knowledgeBase[initial[1]]?initial[1]:null;knowledgeState.topic=null;}else if(initial[0]==='course'&&initial[1])state.activeCourse=initial[1];else if(initial[0]==='openwork'&&window.E8_OPEN_WORK?.[initial[1]?.split('|')[0]]){const [courseId,variant]=initial[1].split('|');state.activeCourse=courseId;state.openWorkVariant=requestedOpenWorkVariant(courseId,variant);}else if(initial[0]==='selfwork'&&window.E8_SELF_WORK?.[initial[1]])state.activeCourse=initial[1];else if(initial[0]==='xpath'&&initial[1])setExtraPathContext(initial[1]);else if(initial[0]==='path'&&initial[1]){state.activeCourse='linear';state.activePath=initial[1];}else if(initial[0]==='qpath'&&initial[1]){state.activeCourse='quadratic';state.activeQuadraticPath=initial[1];}else if(initial[0]==='spath'&&initial[1]){state.activeCourse='sequences';state.activeSequencePath=initial[1];}else if(initial[0]==='apath'&&initial[1]){state.activeCourse='equations';state.activeAlgebraPath=initial[1];}else if(initial[0]==='exam'&&initial[1])state.examCourse=initial[1];else if(initial[0]==='review')restoreReviewCourse();else if(initial[1]&&tasks[initial[1]]){state.task=initial[1];state.activeCourse=tasks[state.task]?.course||'linear';if(state.activeCourse==='quadratic')state.activeQuadraticPath=tasks[state.task]?.path||state.activeQuadraticPath;else if(state.activeCourse==='sequences')state.activeSequencePath=tasks[state.task]?.path||state.activeSequencePath;else if(state.activeCourse==='equations')state.activeAlgebraPath=tasks[state.task]?.path||state.activeAlgebraPath;else if(extraSubjectSpecs[state.activeCourse])state.activeExtraPath=tasks[state.task]?.path||state.activeExtraPath;else state.activePath=tasks[state.task]?.path||state.activePath;if(state.route==='learn')restoreTaskProgress(state.task);}}
// The legacy knowledge module only knows matura course IDs. Restore E8 knowledge
