function registerE8WebMCP(){
  const context=document.modelContext;
  if(!window.SMART_E8||!context?.registerTool||window.__smartE8WebMCP)return;
  window.__smartE8WebMCP=true;
  const register=tool=>{try{void Promise.resolve(context.registerTool(tool)).catch(()=>{});}catch(e){}};
  register({name:'get_e8_progress',title:'Sprawdź postęp E8',description:'Zwraca cel ucznia, liczbę opanowanych elementów i postęp w każdym kursie matematycznym.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return{goalPercent:saved.scoreGoal,mastered:allMasteredCount(),total:allLearningTaskIds.length,courses:courses.map(course=>({id:course.id,title:course.title,progressPercent:coursePercent(course)}))};}});
  register({name:'open_e8_course',title:'Otwórz kurs E8',description:'Otwiera wskazany kurs matematyczny w panelu ucznia.',inputSchema:{type:'object',properties:{courseId:{type:'string',enum:courses.map(course=>course.id)}},required:['courseId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const courseId=String(input?.courseId||'');if(!courses.some(course=>course.id===courseId))throw new Error('Nieznany kurs E8.');state.activeCourse=courseId;routeTo('course',courseId);return{opened:true,courseId,title:courseById(courseId).title};}});
  register({name:'open_e8_exam',title:'Otwórz pełną próbę E8',description:'Otwiera ekran przygotowania pełnej próby egzaminu ósmoklasisty z matematyki; nie uruchamia jeszcze licznika czasu.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(){routeTo('exam','mixed');return{opened:true,tasks:20,points:30,durationMinutes:125};}});
}
registerE8WebMCP();
